use std::path::Path;

use git2::Repository;

use crate::config::EngramConfig;
use crate::error::CoreError;
use crate::model::{EngramData, EngramId, Manifest};

use super::objects::create_engram_objects;
use super::read;
use super::refs;

/// Options for listing engrams.
#[derive(Debug, Clone, Default)]
pub struct ListOptions {
    pub limit: Option<usize>,
    pub agent_filter: Option<String>,
}

/// The main storage interface for engram operations.
pub struct GitStorage {
    repo: Repository,
}

impl GitStorage {
    /// Open the Git repository at the given path.
    pub fn open(path: &Path) -> Result<Self, CoreError> {
        let repo = Repository::open(path)?;
        Ok(Self { repo })
    }

    /// Discover the Git repository from the current directory.
    pub fn discover() -> Result<Self, CoreError> {
        let repo = Repository::discover(".")?;
        Ok(Self { repo })
    }

    /// Check if engram has been initialized in this repo.
    pub fn is_initialized(&self) -> bool {
        self.repo
            .config()
            .ok()
            .and_then(|c| c.get_bool("engram.enabled").ok())
            .unwrap_or(false)
    }

    /// Initialize engram in this repo: set config, configure refspecs.
    pub fn init(&self) -> Result<(), CoreError> {
        let mut config = self.repo.config().map_err(CoreError::Git)?;
        let engram_config = EngramConfig::default_init();
        engram_config.save(&mut config)?;

        // Set schema version
        config
            .set_i32("engram.version", 1)
            .map_err(CoreError::Git)?;

        // Add engram fetch/push refspecs to all configured remotes
        self.configure_remotes()?;

        Ok(())
    }

    /// Create a new engram and store it as Git objects.
    pub fn create(&self, data: &EngramData) -> Result<EngramId, CoreError> {
        let commit_oid = create_engram_objects(&self.repo, data)?;
        let id = data.manifest.id.clone();
        refs::create_engram_ref(&self.repo, &id, commit_oid)?;
        Ok(id)
    }

    /// Read an engram by its ID (or prefix).
    pub fn read(&self, id_or_prefix: &str) -> Result<EngramData, CoreError> {
        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
        read::read_engram(&self.repo, oid)
    }

    /// Read only the manifest (fast path for listing).
    pub fn read_manifest(&self, id_or_prefix: &str) -> Result<Manifest, CoreError> {
        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
        read::read_manifest(&self.repo, oid)
    }

    /// List all engrams, optionally filtered.
    pub fn list(&self, opts: &ListOptions) -> Result<Vec<Manifest>, CoreError> {
        let all_refs = refs::list_engram_refs(&self.repo)?;
        let mut manifests = Vec::with_capacity(all_refs.len());

        for (_id, oid) in &all_refs {
            match read::read_manifest(&self.repo, *oid) {
                Ok(manifest) => {
                    // Apply agent filter
                    if let Some(agent) = &opts.agent_filter {
                        if !manifest.agent.name.contains(agent.as_str()) {
                            continue;
                        }
                    }
                    manifests.push(manifest);
                }
                Err(e) => {
                    tracing::warn!("Skipping unreadable engram: {e}");
                }
            }
        }

        // Sort by created_at descending (most recent first)
        manifests.sort_by(|a, b| b.created_at.cmp(&a.created_at));

        // Apply limit
        if let Some(limit) = opts.limit {
            manifests.truncate(limit);
        }

        Ok(manifests)
    }

    /// Delete an engram by removing its ref.
    pub fn delete(&self, id_or_prefix: &str) -> Result<(), CoreError> {
        let (id, _oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
        refs::delete_engram_ref(&self.repo, &id)
    }

    /// Get the underlying git2::Repository reference.
    pub fn repo(&self) -> &Repository {
        &self.repo
    }

    /// Get the repo working directory path.
    pub fn workdir(&self) -> Option<&Path> {
        self.repo.workdir()
    }

    /// Configure fetch/push refspecs for engram refs on all remotes.
    fn configure_remotes(&self) -> Result<(), CoreError> {
        let remotes = self.repo.remotes().map_err(CoreError::Git)?;
        let mut config = self.repo.config().map_err(CoreError::Git)?;

        for remote_name in remotes.iter().flatten() {
            let fetch_key = format!("remote.{remote_name}.fetch");
            let push_key = format!("remote.{remote_name}.push");
            let fetch_refspec = "+refs/engrams/*:refs/engrams/*";
            let push_refspec = "refs/engrams/*:refs/engrams/*";

            // Check if already configured by iterating existing values
            let fetch_exists = config
                .entries(Some(&fetch_key))
                .ok()
                .map(|mut entries| {
                    let mut found = false;
                    while let Some(Ok(entry)) = entries.next() {
                        if entry.value() == Some(fetch_refspec) {
                            found = true;
                            break;
                        }
                    }
                    found
                })
                .unwrap_or(false);

            if !fetch_exists {
                config
                    .set_multivar(&fetch_key, "^$", fetch_refspec)
                    .or_else(|_| {
                        // If set_multivar fails (no existing entry), try adding
                        self.repo
                            .remote_add_fetch(remote_name, fetch_refspec)
                            .map(|_| ())
                    })
                    .map_err(CoreError::Git)?;
            }

            let push_exists = config
                .entries(Some(&push_key))
                .ok()
                .map(|mut entries| {
                    let mut found = false;
                    while let Some(Ok(entry)) = entries.next() {
                        if entry.value() == Some(push_refspec) {
                            found = true;
                            break;
                        }
                    }
                    found
                })
                .unwrap_or(false);

            if !push_exists {
                config
                    .set_multivar(&push_key, "^$", push_refspec)
                    .or_else(|_| {
                        self.repo
                            .remote_add_push(remote_name, push_refspec)
                            .map(|_| ())
                    })
                    .map_err(CoreError::Git)?;
            }
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::*;
    use chrono::Utc;
    use tempfile::TempDir;

    fn make_test_data() -> EngramData {
        EngramData {
            manifest: Manifest {
                id: EngramId::new(),
                version: 1,
                created_at: Utc::now(),
                finished_at: None,
                agent: AgentInfo {
                    name: "test-agent".into(),
                    model: Some("test-model".into()),
                    version: None,
                },
                git_commits: vec![],
                token_usage: TokenUsage::default(),
                summary: Some("Test engram".into()),
                tags: vec![],
                capture_mode: CaptureMode::Sdk,
            },
            intent: Intent {
                original_request: "Test request".into(),
                interpreted_goal: None,
                summary: None,
                dead_ends: vec![],
                decisions: vec![],
            },
            transcript: Transcript::default(),
            operations: Operations::default(),
            lineage: Lineage::default(),
        }
    }

    #[test]
    fn test_full_lifecycle() {
        let tmp = TempDir::new().unwrap();
        Repository::init(tmp.path()).unwrap();

        let storage = GitStorage::open(tmp.path()).unwrap();

        // Not initialized yet
        assert!(!storage.is_initialized());

        // Init
        storage.init().unwrap();
        assert!(storage.is_initialized());

        // Empty list
        let manifests = storage.list(&ListOptions::default()).unwrap();
        assert!(manifests.is_empty());

        // Create
        let data = make_test_data();
        let id = data.manifest.id.clone();
        let created_id = storage.create(&data).unwrap();
        assert_eq!(created_id, id);

        // List
        let manifests = storage.list(&ListOptions::default()).unwrap();
        assert_eq!(manifests.len(), 1);
        assert_eq!(manifests[0].id, id);

        // Read
        let loaded = storage.read(id.as_str()).unwrap();
        assert_eq!(loaded.manifest.id, id);
        assert_eq!(loaded.intent.original_request, "Test request");

        // Read manifest only
        let manifest = storage.read_manifest(id.as_str()).unwrap();
        assert_eq!(manifest.summary, Some("Test engram".into()));

        // Delete
        storage.delete(id.as_str()).unwrap();
        let manifests = storage.list(&ListOptions::default()).unwrap();
        assert!(manifests.is_empty());
    }

    #[test]
    fn test_list_with_filter() {
        let tmp = TempDir::new().unwrap();
        Repository::init(tmp.path()).unwrap();
        let storage = GitStorage::open(tmp.path()).unwrap();
        storage.init().unwrap();

        // Create two engrams with different agents
        let mut data1 = make_test_data();
        data1.manifest.agent.name = "claude-code".into();
        storage.create(&data1).unwrap();

        let mut data2 = make_test_data();
        data2.manifest.agent.name = "aider".into();
        storage.create(&data2).unwrap();

        // Filter by agent
        let opts = ListOptions {
            agent_filter: Some("claude".into()),
            ..Default::default()
        };
        let manifests = storage.list(&opts).unwrap();
        assert_eq!(manifests.len(), 1);
        assert_eq!(manifests[0].agent.name, "claude-code");

        // No filter
        let all = storage.list(&ListOptions::default()).unwrap();
        assert_eq!(all.len(), 2);
    }

    #[test]
    fn test_list_with_limit() {
        let tmp = TempDir::new().unwrap();
        Repository::init(tmp.path()).unwrap();
        let storage = GitStorage::open(tmp.path()).unwrap();
        storage.init().unwrap();

        for _ in 0..5 {
            storage.create(&make_test_data()).unwrap();
        }

        let opts = ListOptions {
            limit: Some(3),
            ..Default::default()
        };
        let manifests = storage.list(&opts).unwrap();
        assert_eq!(manifests.len(), 3);
    }
}

pub mod format;

#[derive(Debug, Clone, Copy, clap::ValueEnum)]
pub enum OutputFormat {
    Text,
    Json,
}

use engram_core::model::{EngramData, Manifest};

use super::OutputFormat;

pub fn format_manifest_list(manifests: &[Manifest], show_cost: bool, fmt: OutputFormat) -> String {
    match fmt {
        OutputFormat::Json => serde_json::to_string_pretty(manifests).unwrap_or_default(),
        OutputFormat::Text => format_manifest_list_text(manifests, show_cost),
    }
}

fn format_manifest_list_text(manifests: &[Manifest], show_cost: bool) -> String {
    if manifests.is_empty() {
        return "No engrams found.".to_string();
    }

    let mut out = String::new();
    for m in manifests {
        let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
        let summary = m.summary.as_deref().unwrap_or("(no summary)");
        let agent = &m.agent.name;
        let model = m.agent.model.as_deref().unwrap_or("");
        let time = m.created_at.format("%Y-%m-%d %H:%M");

        if show_cost {
            let tokens = m.token_usage.total_tokens;
            let cost = m
                .token_usage
                .cost_usd
                .map(|c| format!("${c:.2}"))
                .unwrap_or_else(|| "-".to_string());
            out.push_str(&format!(
                "\u{25c6} {short_id} {summary} [{agent}/{model}] {cost} {tokens}tok  {time}\n"
            ));
        } else {
            out.push_str(&format!(
                "\u{25c6} {short_id} {summary} [{agent}/{model}]  {time}\n"
            ));
        }
    }
    out
}

pub fn format_engram_full(data: &EngramData, fmt: OutputFormat) -> String {
    match fmt {
        OutputFormat::Json => serde_json::to_string_pretty(&data.manifest).unwrap_or_default(),
        OutputFormat::Text => format_engram_full_text(data),
    }
}

fn format_engram_full_text(data: &EngramData) -> String {
    let m = &data.manifest;
    let mut out = String::new();

    out.push_str(&format!("Engram: {}\n", m.id));
    out.push_str(&format!(
        "Agent:  {}{}\n",
        m.agent.name,
        m.agent
            .model
            .as_ref()
            .map(|m| format!(" ({m})"))
            .unwrap_or_default()
    ));
    out.push_str(&format!("Date:   {}\n", m.created_at.format("%Y-%m-%d %H:%M:%S UTC")));
    if let Some(summary) = &m.summary {
        out.push_str(&format!("Summary: {summary}\n"));
    }

    // Token usage
    let tu = &m.token_usage;
    if tu.total_tokens > 0 {
        out.push_str(&format!(
            "Tokens: {} total ({} in, {} out)",
            tu.total_tokens, tu.input_tokens, tu.output_tokens
        ));
        if let Some(cost) = tu.cost_usd {
            out.push_str(&format!("  Cost: ${cost:.4}"));
        }
        out.push('\n');
    }

    if !m.git_commits.is_empty() {
        out.push_str(&format!("Commits: {}\n", m.git_commits.join(", ")));
    }

    if !m.tags.is_empty() {
        out.push_str(&format!("Tags: {}\n", m.tags.join(", ")));
    }

    // Intent
    out.push_str("\n--- Intent ---\n");
    out.push_str(&data.intent.to_markdown());

    // Operations summary
    if !data.operations.file_changes.is_empty() {
        out.push_str("\n--- File Changes ---\n");
        for fc in &data.operations.file_changes {
            let symbol = match &fc.change_type {
                engram_core::model::FileChangeType::Created => "+",
                engram_core::model::FileChangeType::Modified => "~",
                engram_core::model::FileChangeType::Deleted => "-",
                engram_core::model::FileChangeType::Renamed { from } => {
                    out.push_str(&format!("  {from} -> {}\n", fc.path));
                    continue;
                }
            };
            out.push_str(&format!("  {symbol} {}\n", fc.path));
        }
    }

    if !data.operations.tool_calls.is_empty() {
        out.push_str(&format!(
            "\n--- Tool Calls ({}) ---\n",
            data.operations.tool_calls.len()
        ));
        for tc in &data.operations.tool_calls {
            let err_marker = if tc.is_error { " [ERROR]" } else { "" };
            out.push_str(&format!("  {}{err_marker}\n", tc.tool_name));
        }
    }

    // Transcript summary
    out.push_str(&format!(
        "\n--- Transcript ({} entries) ---\n",
        data.transcript.entries.len()
    ));

    out
}

pub fn format_intent(data: &EngramData, fmt: OutputFormat) -> String {
    match fmt {
        OutputFormat::Json => serde_json::to_string_pretty(&data.intent).unwrap_or_default(),
        OutputFormat::Text => data.intent.to_markdown(),
    }
}

