 12→impl AiderImporter {
 13→    /// Discover aider history files in a repo.
 14→    pub fn discover(repo_root: &Path) -> Result<Vec<std::path::PathBuf>, CaptureError> {
 15→        let history_path = repo_root.join(".aider.chat.history.md");
 16→        if history_path.exists() {
 17→            Ok(vec![history_path])
 18→        } else {
 19→            Ok(Vec::new())
 20→        }
 21→    }
 22→
 23→    /// Import from .aider.chat.history.md.
 24→    /// Returns one EngramData per session (delimited by "# aider chat started at").
 25→    pub fn import_history(path: &Path) -> Result<Vec<EngramData>, CaptureError> {
 26→        let content = std::fs::read_to_string(path).map_err(CaptureError::Io)?;
 27→        parse_aider_history(&content)
 28→    }
 29→}
