 54→fn parse_aider_session(session_text: &str) -> Result<Option<EngramData>, CaptureError> {
 55→    let mut transcript_entries = Vec::new();
 56→    let mut original_request = String::new();
 57→    let mut total_tokens_sent: u64 = 0;
 58→    let mut total_tokens_received: u64 = 0;
 59→    let mut total_cost: f64 = 0.0;
 60→
 61→    let mut current_role: Option<Role> = None;
 62→    let mut current_text = String::new();
 63→    let now = Utc::now();
 64→
 65→    for line in session_text.lines() {
 66→        // User message starts with ####
 67→        if let Some(user_msg) = line.strip_prefix("#### ") {
 68→            // Save any previous accumulated text
 69→            flush_entry(
 70→                &mut transcript_entries,
 71→                &current_role,
 72→                &current_text,
 73→                now,
 74→            );
 75→
 76→            let msg = user_msg.trim().to_string();
 77→            if original_request.is_empty() && !msg.is_empty() {
 78→                original_request = msg.clone();
 79→            }
 80→
 81→            if !msg.is_empty() {
 82→                transcript_entries.push(TranscriptEntry {
 83→                    timestamp: now,
 84→                    role: Role::User,
 85→                    content: TranscriptContent::Text { text: msg },
 86→                    token_count: None,
 87→                });
 88→            }
 89→            current_role = None;
 90→            current_text.clear();
 91→            continue;
 92→        }
 93→
 94→        // Tool output / system messages start with >
 95→        if line.starts_with("> ") {
 96→            let tool_text = line.strip_prefix("> ").unwrap_or(line);
 97→
 98→            // Parse token/cost lines: "Tokens: 3.2k sent, 245 received. Cost: $0.01"
 99→            if tool_text.starts_with("Tokens:") {
100→                parse_token_line(
101→                    tool_text,
102→                    &mut total_tokens_sent,
103→                    &mut total_tokens_received,
104→                    &mut total_cost,
105→                );
106→            }
107→            continue;
108→        }
109→
110→        // Unprefixed text = assistant response
111→        if !line.is_empty() {
112→            if current_role.is_none() {
113→                current_role = Some(Role::Assistant);
114→            }
115→            if !current_text.is_empty() {
116→                current_text.push('\n');
117→            }
118→            current_text.push_str(line);
119→        }
120→    }
121→
122→    // Flush last entry
123→    flush_entry(
124→        &mut transcript_entries,
125→        &current_role,
126→        &current_text,
127→        now,
128→    );
129→
130→    if transcript_entries.is_empty() {
131→        return Ok(None);
132→    }
133→
134→    let id = EngramId::new();
135→    let token_usage = TokenUsage {
136→        input_tokens: total_tokens_sent,
137→        output_tokens: total_tokens_received,
138→        total_tokens: total_tokens_sent + total_tokens_received,
139→        cost_usd: if total_cost > 0.0 {
140→            Some(total_cost)
141→        } else {
142→            None
143→        },
144→        ..Default::default()
145→    };
146→
147→    let manifest = Manifest {
148→        id,
149→        version: 1,
150→        created_at: now,
151→        finished_at: Some(now),
152→        agent: AgentInfo {
153→            name: "aider".into(),
154→            model: None,
155→            version: None,
156→        },
157→        git_commits: Vec::new(),
158→        token_usage,
159→        summary: if original_request.len() > 100 {
160→            Some(format!("{}...", &original_request[..100]))
161→        } else if original_request.is_empty() {
162→            Some("Imported Aider session".into())
163→        } else {
164→            Some(original_request.clone())
165→        },
166→        tags: Vec::new(),
167→        capture_mode: CaptureMode::Import,
168→    };
169→
170→    let intent = Intent {
171→        original_request: if original_request.is_empty() {
172→            "Imported Aider session".into()
173→        } else {
174→            original_request
175→        },
176→        interpreted_goal: None,
177→        summary: manifest.summary.clone(),
178→        dead_ends: Vec::new(),
179→        decisions: Vec::new(),
180→    };
181→
182→    Ok(Some(EngramData {
183→        manifest,
184→        intent,
185→        transcript: Transcript {
186→            entries: transcript_entries,
187→        },
188→        operations: Operations::default(),
189→        lineage: Lineage::default(),
190→    }))
191→}
192→
193→fn flush_entry(
194→    entries: &mut Vec<TranscriptEntry>,
195→    role: &Option<Role>,
196→    text: &str,
197→    ts: chrono::DateTime<Utc>,
198→) {
199→    if let Some(role) = role {
200→        let trimmed = text.trim();
201→        if !trimmed.is_empty() {
202→            entries.push(TranscriptEntry {
203→                timestamp: ts,
204→                role: role.clone(),
205→                content: TranscriptContent::Text {
206→                    text: trimmed.to_string(),
207→                },
208→                token_count: None,
209→            });
210→        }
211→    }
212→}
213→
214→fn parse_token_line(
215→    line: &str,
216→    sent: &mut u64,
217→    received: &mut u64,
218→    cost: &mut f64,
219→) {
220→    // Format: "Tokens: 3.2k sent, 245 received. Cost: $0.01"
221→    // or: "Tokens: 3200 sent, 245 received."
222→    for part in line.split([',', '.']) {
223→        let part = part.trim();
224→        if part.contains("sent") {
225→            if let Some(num) = extract_token_count(part) {
226→                *sent += num;
227→            }
228→        } else if part.contains("received") {
229→            if let Some(num) = extract_token_count(part) {
230→                *received += num;
231→            }
232→        } else if part.contains('$') {
233→            if let Some(c) = extract_cost(part) {
234→                *cost += c;
235→            }
236→        }
237→    }
238→}
239→
240→fn extract_token_count(s: &str) -> Option<u64> {
241→    // Find a number (possibly with k/m suffix)
242→    for word in s.split_whitespace() {
243→        let word = word.trim_matches(|c: char| !c.is_ascii_digit() && c != '.' && c != 'k' && c != 'K' && c != 'm' && c != 'M');
244→        if word.is_empty() {
245→            continue;
246→        }
247→        if let Some(num_str) = word.strip_suffix('k').or_else(|| word.strip_suffix('K')) {
248→            if let Ok(n) = num_str.parse::<f64>() {
249→                return Some((n * 1000.0) as u64);
250→            }
251→        } else if let Some(num_str) = word.strip_suffix('m').or_else(|| word.strip_suffix('M')) {
252→            if let Ok(n) = num_str.parse::<f64>() {
253→                return Some((n * 1_000_000.0) as u64);
254→            }
255→        } else if let Ok(n) = word.parse::<u64>() {
256→            return Some(n);
257→        }
258→    }
259→    None
260→}
261→
262→fn extract_cost(s: &str) -> Option<f64> {
263→    for word in s.split_whitespace() {
264→        if let Some(num_str) = word.strip_prefix('$') {
265→            if let Ok(c) = num_str.parse::<f64>() {
266→                return Some(c);
267→            }
268→        }
269→    }
270→    None

