 2→//!
 3→//! # Example
 4→//! ```no_run
 5→//! use engram_sdk::EngramSession;
 6→//!
 7→//! let mut session = EngramSession::begin("my-agent", Some("gpt-4"));
 8→//! session.log_message("user", "Add authentication to the API");
 9→//! session.log_message("assistant", "I'll add JWT-based authentication.");
10→//! session.log_tool_call("write_file", r#"{"path":"src/auth.rs"}"#, Some("Created auth module"));
11→//! session.log_file_change("src/auth.rs", "created");
12→//! session.log_rejection("Session-based auth", "Too much server-side state for a stateless API");
13→//! session.add_tokens(1500, 800, Some(0.02));
14→//! let id = session.commit(Some("abc123"), Some("Add JWT auth")).unwrap();
15→//! println!("Engram stored: {id}");
16→//! ```
