 13→/// Options for listing engrams.
 14→#[derive(Debug, Clone, Default)]
 15→pub struct ListOptions {
 16→    pub limit: Option<usize>,
 17→    pub agent_filter: Option<String>,
 18→}
 19→
 20→/// The main storage interface for engram operations.
 21→pub struct GitStorage {
 22→    repo: Repository,
 23→}
 24→
 25→impl GitStorage {
 26→    /// Open the Git repository at the given path.
 27→    pub fn open(path: &Path) -> Result<Self, CoreError> {
 28→        let repo = Repository::open(path)?;
 29→        Ok(Self { repo })
 30→    }
 31→
 32→    /// Discover the Git repository from the current directory.
 33→    pub fn discover() -> Result<Self, CoreError> {
 34→        let repo = Repository::discover(".")?;
 35→        Ok(Self { repo })
 36→    }
 37→
 38→    /// Check if engram has been initialized in this repo.
 39→    pub fn is_initialized(&self) -> bool {
 40→        self.repo
 41→            .config()
 42→            .ok()
 43→            .and_then(|c| c.get_bool("engram.enabled").ok())
 44→            .unwrap_or(false)
 45→    }
 46→
 47→    /// Initialize engram in this repo: set config, configure refspecs.
 48→    pub fn init(&self) -> Result<(), CoreError> {
 49→        let mut config = self.repo.config().map_err(CoreError::Git)?;
 50→        let engram_config = EngramConfig::default_init();
 51→        engram_config.save(&mut config)?;
 52→
 53→        // Set schema version
 54→        config
 55→            .set_i32("engram.version", 1)
 56→            .map_err(CoreError::Git)?;
 57→
 58→        // Add engram fetch/push refspecs to all configured remotes
 59→        self.configure_remotes()?;
 60→
 61→        Ok(())
 62→    }
 63→
 64→    /// Create a new engram and store it as Git objects.
 65→    pub fn create(&self, data: &EngramData) -> Result<EngramId, CoreError> {
 66→        let commit_oid = create_engram_objects(&self.repo, data)?;
 67→        let id = data.manifest.id.clone();
 68→        refs::create_engram_ref(&self.repo, &id, commit_oid)?;
 69→        Ok(id)
 70→    }
 71→
 72→    /// Read an engram by its ID (or prefix).
 73→    pub fn read(&self, id_or_prefix: &str) -> Result<EngramData, CoreError> {
 74→        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
 75→        read::read_engram(&self.repo, oid)
 76→    }
 77→
 78→    /// Read only the manifest (fast path for listing).
 79→    pub fn read_manifest(&self, id_or_prefix: &str) -> Result<Manifest, CoreError> {
 80→        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
 81→        read::read_manifest(&self.repo, oid)
 82→    }
 83→
 84→    /// List all engrams, optionally filtered.
 85→    pub fn list(&self, opts: &ListOptions) -> Result<Vec<Manifest>, CoreError> {
 86→        let all_refs = refs::list_engram_refs(&self.repo)?;
 87→        let mut manifests = Vec::with_capacity(all_refs.len());
 88→
 89→        for (_id, oid) in &all_refs {
 90→            match read::read_manifest(&self.repo, *oid) {
 91→                Ok(manifest) => {
 92→                    // Apply agent filter
 93→                    if let Some(agent) = &opts.agent_filter {
 94→                        if !manifest.agent.name.contains(agent.as_str()) {
 95→                            continue;
 96→                        }
 97→                    }
 98→                    manifests.push(manifest);
 99→                }
100→                Err(e) => {
101→                    tracing::warn!("Skipping unreadable engram: {e}");
102→                }
103→            }
104→        }
105→
106→        // Sort by created_at descending (most recent first)
107→        manifests.sort_by(|a, b| b.created_at.cmp(&a.created_at));
108→
109→        // Apply limit
110→        if let Some(limit) = opts.limit {
111→            manifests.truncate(limit);
112→        }
113→
114→        Ok(manifests)
115→    }
116→
117→    /// Delete an engram by removing its ref.
118→    pub fn delete(&self, id_or_prefix: &str) -> Result<(), CoreError> {
119→        let (id, _oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
120→        refs::delete_engram_ref(&self.repo, &id)
121→    }
122→
123→    /// Get the underlying git2::Repository reference.
124→    pub fn repo(&self) -> &Repository {
125→        &self.repo
126→    }
127→
128→    /// Get the repo working directory path.
129→    pub fn workdir(&self) -> Option<&Path> {
130→        self.repo.workdir()
131→    }
132→
133→    /// Configure fetch/push refspecs for engram refs on all remotes.
134→    fn configure_remotes(&self) -> Result<(), CoreError> {
135→        let remotes = self.repo.remotes().map_err(CoreError::Git)?;
136→        let mut config = self.repo.config().map_err(CoreError::Git)?;
137→
138→        for remote_name in remotes.iter().flatten() {
139→            let fetch_key = format!("remote.{remote_name}.fetch");
140→            let push_key = format!("remote.{remote_name}.push");
141→            let fetch_refspec = "+refs/engrams/*:refs/engrams/*";
142→            let push_refspec = "refs/engrams/*:refs/engrams/*";
143→
144→            // Check if already configured by iterating existing values
145→            let fetch_exists = config
146→                .entries(Some(&fetch_key))
147→                .ok()
148→                .map(|mut entries| {
149→                    let mut found = false;
150→                    while let Some(Ok(entry)) = entries.next() {
151→                        if entry.value() == Some(fetch_refspec) {
152→                            found = true;
153→                            break;
154→                        }
155→                    }
156→                    found
157→                })
158→                .unwrap_or(false);
159→
160→            if !fetch_exists {
161→                config
162→                    .set_multivar(&fetch_key, "^$", fetch_refspec)
163→                    .or_else(|_| {
164→                        // If set_multivar fails (no existing entry), try adding
165→                        self.repo
166→                            .remote_add_fetch(remote_name, fetch_refspec)
167→                            .map(|_| ())
168→                    })
169→                    .map_err(CoreError::Git)?;
170→            }
171→
172→            let push_exists = config
173→                .entries(Some(&push_key))
174→                .ok()
175→                .map(|mut entries| {
176→                    let mut found = false;
177→                    while let Some(Ok(entry)) = entries.next() {
178→                        if entry.value() == Some(push_refspec) {
179→                            found = true;
180→                            break;
181→                        }
182→                    }
183→                    found
184→                })
185→                .unwrap_or(false);
186→
187→            if !push_exists {
188→                config
189→                    .set_multivar(&push_key, "^$", push_refspec)
190→                    .or_else(|_| {
191→                        self.repo
192→                            .remote_add_push(remote_name, push_refspec)
193→                            .map(|_| ())
194→                    })
195→                    .map_err(CoreError::Git)?;
196→            }
197→        }
198→
199→        Ok(())
200→    }
201→}
