 1→use anyhow::{Context, Result};
 2→use clap::Args;
 3→use engram_core::storage::GitStorage;
 4→
 5→use crate::output::format::{format_engram_full, format_intent};
 6→use crate::output::OutputFormat;
 7→
 8→#[derive(Args)]
 9→pub struct ShowArgs {
10→    /// Engram ID (full or prefix)
11→    pub id: String,
12→
13→    /// Show only the intent
14→    #[arg(long)]
15→    pub intent: bool,
16→
17→    /// Show only the transcript (as JSONL)
18→    #[arg(long)]
19→    pub transcript: bool,
20→
21→    /// Show only operations
22→    #[arg(long)]
23→    pub operations: bool,
24→}
25→
26→pub fn run(args: &ShowArgs, format: OutputFormat) -> Result<()> {
27→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
28→
29→    if !storage.is_initialized() {
30→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
31→    }
32→
33→    let data = storage
34→        .read(&args.id)
35→        .with_context(|| format!("Failed to read engram '{}'", args.id))?;
36→
37→    let output = if args.intent {
38→        format_intent(&data, format)
39→    } else if args.transcript {
40→        match format {
41→            OutputFormat::Json => {
42→                serde_json::to_string_pretty(&data.transcript.entries).unwrap_or_default()
43→            }
44→            OutputFormat::Text => String::from_utf8_lossy(&data.transcript.to_jsonl()).to_string(),
45→        }
46→    } else if args.operations {
47→        serde_json::to_string_pretty(&data.operations).unwrap_or_default()
48→    } else {
49→        format_engram_full(&data, format)
50→    };
51→
52→    println!("{output}");
53→    Ok(())
54→}
