 1→use engram_core::model::Manifest;
 2→use engram_core::storage::GitStorage;
 3→
 4→use crate::error::QueryError;
 5→use crate::search::SearchEngine;
 6→
 7→/// An entry in a file's reasoning trace.
 8→#[derive(Debug, Clone)]
 9→pub struct TraceEntry {
10→    pub manifest: Manifest,
11→    pub change_type: String,
12→}
13→
14→/// Trace all engrams that touched a file, ordered by time.
15→pub fn trace_file(
16→    storage: &GitStorage,
17→    search: &SearchEngine,
18→    file_path: &str,
19→) -> Result<Vec<TraceEntry>, QueryError> {
20→    let results = search.search_by_file(storage, file_path, 100)?;
21→
22→    let mut entries: Vec<TraceEntry> = results
23→        .into_iter()
24→        .map(|r| {
25→            // Try to find the specific change type for this file
26→            let change_type = "modified".to_string(); // Default; full data not in search result
27→            TraceEntry {
28→                manifest: r.manifest,
29→                change_type,
30→            }
31→        })
32→        .collect();
33→
34→    // Sort by creation time (oldest first for a trace)
35→    entries.sort_by_key(|e| e.manifest.created_at);
36→
37→    Ok(entries)
38→}
