"""Data model types matching the Rust engram-core model."""

from __future__ import annotations

import json
import uuid
from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
from typing import Any


def _new_engram_id() -> str:
    """Generate a new engram ID (UUID v4 hex, no dashes)."""
    return uuid.uuid4().hex


def _now() -> datetime:
    return datetime.now(timezone.utc)


class CaptureMode(str, Enum):
    WRAPPER = "Wrapper"
    IMPORT = "Import"
    SDK = "Sdk"


class FileChangeType(str, Enum):
    CREATED = "Created"
    MODIFIED = "Modified"
    DELETED = "Deleted"
    # Renamed is handled separately since it carries data


@dataclass
class AgentInfo:
    name: str
    model: str | None = None
    version: str | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {"name": self.name}
        if self.model is not None:
            d["model"] = self.model
        if self.version is not None:
            d["version"] = self.version
        return d

    @classmethod
    def from_dict(cls, d: dict) -> AgentInfo:
        return cls(name=d["name"], model=d.get("model"), version=d.get("version"))


@dataclass
class TokenUsage:
    input_tokens: int = 0
    output_tokens: int = 0
    cache_read_tokens: int = 0
    cache_write_tokens: int = 0
    total_tokens: int = 0
    cost_usd: float | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "input_tokens": self.input_tokens,
            "output_tokens": self.output_tokens,
            "cache_read_tokens": self.cache_read_tokens,
            "cache_write_tokens": self.cache_write_tokens,
            "total_tokens": self.total_tokens,
        }
        if self.cost_usd is not None:
            d["cost_usd"] = self.cost_usd
        return d

    @classmethod
    def from_dict(cls, d: dict) -> TokenUsage:
        return cls(
            input_tokens=d.get("input_tokens", 0),
            output_tokens=d.get("output_tokens", 0),
            cache_read_tokens=d.get("cache_read_tokens", 0),
            cache_write_tokens=d.get("cache_write_tokens", 0),
            total_tokens=d.get("total_tokens", 0),
            cost_usd=d.get("cost_usd"),
        )


@dataclass
class DeadEnd:
    approach: str
    reason: str

    def to_dict(self) -> dict:
        return {"approach": self.approach, "reason": self.reason}

    @classmethod
    def from_dict(cls, d: dict) -> DeadEnd:
        return cls(approach=d["approach"], reason=d["reason"])


@dataclass
class Decision:
    description: str
    rationale: str

    def to_dict(self) -> dict:
        return {"description": self.description, "rationale": self.rationale}

    @classmethod
    def from_dict(cls, d: dict) -> Decision:
        return cls(description=d["description"], rationale=d["rationale"])


@dataclass
class Intent:
    original_request: str
    interpreted_goal: str | None = None
    summary: str | None = None
    dead_ends: list[DeadEnd] = field(default_factory=list)
    decisions: list[Decision] = field(default_factory=list)

    def to_markdown(self) -> str:
        lines = ["# Intent", "", f"## Original Request", "", self.original_request, ""]
        if self.summary:
            lines.extend(["## Summary", "", self.summary, ""])
        if self.dead_ends:
            lines.extend(["## Dead Ends", ""])
            for de in self.dead_ends:
                lines.append(f"- **{de.approach}**: {de.reason}")
            lines.append("")
        if self.decisions:
            lines.extend(["## Decisions", ""])
            for d in self.decisions:
                lines.append(f"- **{d.description}**: {d.rationale}")
            lines.append("")
        return "\n".join(lines)


@dataclass
class TranscriptEntry:
    timestamp: datetime
    role: str  # "user", "assistant", "system", "tool"
    content: dict  # {"type": "text", "text": "..."} or {"type": "tool_use", ...}
    token_count: int | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "timestamp": self.timestamp.isoformat(),
            "role": self.role,
            "content": self.content,
        }
        if self.token_count is not None:
            d["token_count"] = self.token_count
        return d

    @classmethod
    def from_dict(cls, d: dict) -> TranscriptEntry:
        return cls(
            timestamp=datetime.fromisoformat(d["timestamp"]),
            role=d["role"],
            content=d["content"],
            token_count=d.get("token_count"),
        )


@dataclass
class Transcript:
    entries: list[TranscriptEntry] = field(default_factory=list)

    def to_jsonl(self) -> bytes:
        lines = [json.dumps(e.to_dict()) for e in self.entries]
        return ("\n".join(lines) + "\n").encode("utf-8") if lines else b""

    @classmethod
    def from_jsonl(cls, data: bytes) -> Transcript:
        entries = []
        for line in data.decode("utf-8").strip().splitlines():
            if line.strip():
                entries.append(TranscriptEntry.from_dict(json.loads(line)))
        return cls(entries=entries)


@dataclass
class ToolCall:
    timestamp: datetime
    tool_name: str
    input: Any
    output_summary: str | None = None
    duration_ms: int | None = None
    is_error: bool = False

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "timestamp": self.timestamp.isoformat(),
            "tool_name": self.tool_name,
            "input": self.input,
            "is_error": self.is_error,
        }
        if self.output_summary is not None:
            d["output_summary"] = self.output_summary
        if self.duration_ms is not None:
            d["duration_ms"] = self.duration_ms
        return d


@dataclass
class FileChange:
    path: str
    change_type: str  # "Created", "Modified", "Deleted", or "Renamed"
    lines_added: int | None = None
    lines_removed: int | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {"path": self.path, "change_type": self.change_type}
        if self.lines_added is not None:
            d["lines_added"] = self.lines_added
        if self.lines_removed is not None:
            d["lines_removed"] = self.lines_removed
        return d


@dataclass
class ShellCommand:
    timestamp: datetime
    command: str
    exit_code: int | None = None
    duration_ms: int | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "timestamp": self.timestamp.isoformat(),
            "command": self.command,
        }
        if self.exit_code is not None:
            d["exit_code"] = self.exit_code
        if self.duration_ms is not None:
            d["duration_ms"] = self.duration_ms
        return d


@dataclass
class Operations:
    tool_calls: list[ToolCall] = field(default_factory=list)
    file_changes: list[FileChange] = field(default_factory=list)
    shell_commands: list[ShellCommand] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "tool_calls": [tc.to_dict() for tc in self.tool_calls],
            "file_changes": [fc.to_dict() for fc in self.file_changes],
            "shell_commands": [sc.to_dict() for sc in self.shell_commands],
        }


@dataclass
class Lineage:
    parent_engram: str | None = None
    child_engrams: list[str] = field(default_factory=list)
    related_engrams: list[dict] = field(default_factory=list)
    git_commits: list[str] = field(default_factory=list)
    branch: str | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "child_engrams": self.child_engrams,
            "related_engrams": self.related_engrams,
            "git_commits": self.git_commits,
        }
        if self.parent_engram is not None:
            d["parent_engram"] = self.parent_engram
        if self.branch is not None:
            d["branch"] = self.branch
        return d


@dataclass
class Manifest:
    id: str
    version: int
    created_at: datetime
    agent: AgentInfo
    token_usage: TokenUsage
    capture_mode: CaptureMode
    finished_at: datetime | None = None
    git_commits: list[str] = field(default_factory=list)
    summary: str | None = None
    tags: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "id": self.id,
            "version": self.version,
            "created_at": self.created_at.isoformat(),
            "agent": self.agent.to_dict(),
            "token_usage": self.token_usage.to_dict(),
            "capture_mode": self.capture_mode.value,
            "git_commits": self.git_commits,
            "tags": self.tags,
        }
        if self.finished_at is not None:
            d["finished_at"] = self.finished_at.isoformat()
        if self.summary is not None:
            d["summary"] = self.summary
        return d

    @classmethod
    def from_dict(cls, d: dict) -> Manifest:
        return cls(
            id=d["id"],
            version=d["version"],
            created_at=datetime.fromisoformat(d["created_at"]),
            finished_at=datetime.fromisoformat(d["finished_at"]) if d.get("finished_at") else None,
            agent=AgentInfo.from_dict(d["agent"]),
            token_usage=TokenUsage.from_dict(d["token_usage"]),
            capture_mode=CaptureMode(d["capture_mode"]),
            git_commits=d.get("git_commits", []),
            summary=d.get("summary"),
            tags=d.get("tags", []),
        )


@dataclass
class EngramData:
    manifest: Manifest
    intent: Intent
    transcript: Transcript
    operations: Operations
    lineage: Lineage

{
  "name": "@engram/sdk",
  "version": "0.1.0",
  "description": "TypeScript SDK for Engram - capture agent reasoning as Git-native versioned data",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "scripts": {
    "build": "tsup src/index.ts --format esm,cjs --dts",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "dependencies": {
    "simple-git": "^3.27.0"
  },
  "devDependencies": {
    "tsup": "^8.0.0",
    "typescript": "^5.7.0",
    "vitest": "^3.0.0"
  },
  "license": "Apache-2.0 OR MIT",
  "engines": {
    "node": ">=18"
  }
}

/**
 * Data model types matching the Rust engram-core model.
 */

import { randomUUID } from "crypto";

export type CaptureMode = "Wrapper" | "Import" | "Sdk";

export type FileChangeType = "Created" | "Modified" | "Deleted";

export interface AgentInfo {
  name: string;
  model?: string;
  version?: string;
}

export interface TokenUsage {
  input_tokens: number;
  output_tokens: number;
  cache_read_tokens: number;
  cache_write_tokens: number;
  total_tokens: number;
  cost_usd?: number;
}

export function defaultTokenUsage(): TokenUsage {
  return {
    input_tokens: 0,
    output_tokens: 0,
    cache_read_tokens: 0,
    cache_write_tokens: 0,
    total_tokens: 0,
  };
}

export interface DeadEnd {
  approach: string;
  reason: string;
}

export interface Decision {
  description: string;
  rationale: string;
}

export interface Intent {
  original_request: string;
  interpreted_goal?: string;
  summary?: string;
  dead_ends: DeadEnd[];
  decisions: Decision[];
}

export interface TranscriptEntry {
  timestamp: string;
  role: string;
  content: Record<string, unknown>;
  token_count?: number;
}

export interface Transcript {
  entries: TranscriptEntry[];
}

export interface ToolCall {
  timestamp: string;
  tool_name: string;
  input: unknown;
  output_summary?: string;
  duration_ms?: number;
  is_error: boolean;
}

export interface FileChange {
  path: string;
  change_type: string;
  lines_added?: number;
  lines_removed?: number;
}

export interface ShellCommand {
  timestamp: string;
  command: string;
  exit_code?: number;
  duration_ms?: number;
}

export interface Operations {
  tool_calls: ToolCall[];
  file_changes: FileChange[];
  shell_commands: ShellCommand[];
}

export interface Lineage {
  parent_engram?: string;
  child_engrams: string[];
  related_engrams: unknown[];
  git_commits: string[];
  branch?: string;
}

export interface Manifest {
  id: string;
  version: number;
  created_at: string;
  finished_at?: string;
  agent: AgentInfo;
  git_commits: string[];
  token_usage: TokenUsage;
  summary?: string;
  tags: string[];
  capture_mode: CaptureMode;
}

export interface EngramData {
  manifest: Manifest;
  intent: Intent;
  transcript: Transcript;
  operations: Operations;
  lineage: Lineage;
}

export function newEngramId(): string {
  return randomUUID().replace(/-/g, "");
}

export function intentToMarkdown(intent: Intent): string {
  const lines: string[] = [
    "# Intent",
    "",
    "## Original Request",
    "",
    intent.original_request,
    "",
  ];

  if (intent.summary) {
    lines.push("## Summary", "", intent.summary, "");
  }

  if (intent.dead_ends.length > 0) {
    lines.push("## Dead Ends", "");
    for (const de of intent.dead_ends) {
      lines.push(`- **${de.approach}**: ${de.reason}`);
    }
    lines.push("");
  }

  if (intent.decisions.length > 0) {
    lines.push("## Decisions", "");
    for (const d of intent.decisions) {
      lines.push(`- **${d.description}**: ${d.rationale}`);
    }
    lines.push("");
  }

  return lines.join("\n");
}

export function transcriptToJsonl(transcript: Transcript): string {
  return transcript.entries.map((e) => JSON.stringify(e)).join("\n") + "\n";
}

/**
 * Git-native storage for engrams using git CLI commands (via simple-git).
 */

import { execSync } from "child_process";
import { readFileSync, readdirSync, statSync } from "fs";
import { join } from "path";
import type { EngramData, Manifest } from "./model.js";
import { intentToMarkdown, transcriptToJsonl } from "./model.js";

const ENGRAM_REF_PREFIX = "refs/engrams/";

function refName(engramId: string): string {
  const prefix = engramId.slice(0, 2);
  return `refs/engrams/${prefix}/${engramId}`;
}

function gitCmd(repoPath: string, args: string, input?: string): string {
  const opts: Parameters<typeof execSync>[1] = {
    cwd: repoPath,
    encoding: "utf-8" as const,
    maxBuffer: 50 * 1024 * 1024,
    stdio: input ? ["pipe", "pipe", "pipe"] : ["pipe", "pipe", "pipe"],
  };
  if (input) {
    (opts as Record<string, unknown>).input = input;
  }
  return execSync(`git ${args}`, opts).toString().trim();
}

export class GitStorage {
  private repoPath: string;

  constructor(repoPath: string) {
    this.repoPath = repoPath;
  }

  static open(path: string): GitStorage {
    return new GitStorage(path);
  }

  static discover(startPath: string = "."): GitStorage {
    const toplevel = execSync("git rev-parse --show-toplevel", {
      cwd: startPath,
      encoding: "utf-8",
    }).trim();
    return new GitStorage(toplevel);
  }

  /**
   * Store an engram as Git objects and create a ref. Returns the engram ID.
   */
  create(data: EngramData): string {
    const manifestJson = JSON.stringify(data.manifest, null, 2);
    const intentMd = intentToMarkdown(data.intent);
    const transcriptJsonl = transcriptToJsonl(data.transcript);
    const operationsJson = JSON.stringify(data.operations, null, 2);
    const lineageJson = JSON.stringify(data.lineage, null, 2);

    // Create blobs
    const manifestOid = gitCmd(this.repoPath, "hash-object -w --stdin", manifestJson);
    const intentOid = gitCmd(this.repoPath, "hash-object -w --stdin", intentMd);
    const transcriptOid = gitCmd(this.repoPath, "hash-object -w --stdin", transcriptJsonl);
    const operationsOid = gitCmd(this.repoPath, "hash-object -w --stdin", operationsJson);
    const lineageOid = gitCmd(this.repoPath, "hash-object -w --stdin", lineageJson);

    // Build tree via mktree
    const treeInput = [
      `100644 blob ${intentOid}\tintent.md`,
      `100644 blob ${lineageOid}\tlineage.json`,
      `100644 blob ${manifestOid}\tmanifest.json`,
      `100644 blob ${operationsOid}\toperations.json`,
      `100644 blob ${transcriptOid}\ttranscript.jsonl`,
    ].join("\n");

    const treeOid = gitCmd(this.repoPath, "mktree", treeInput);

    // Create commit
    const summary = data.manifest.summary || "engram session";
    const commitOid = gitCmd(
      this.repoPath,
      `commit-tree ${treeOid} -m "engram: ${summary}"`,
    );

    // Create ref
    const ref = refName(data.manifest.id);
    gitCmd(this.repoPath, `update-ref ${ref} ${commitOid}`);

    return data.manifest.id;
  }

  /**
   * Read an engram by its ID (or prefix).
   */
  read(idOrPrefix: string): EngramData {
    const resolvedRef = this.resolve(idOrPrefix);
    const commitOid = gitCmd(this.repoPath, `rev-parse ${resolvedRef}`);

    // Get tree from commit
    const treeOid = gitCmd(this.repoPath, `rev-parse ${commitOid}^{tree}`);

    // Read each blob
    const manifestJson = gitCmd(this.repoPath, `cat-file blob ${treeOid}:manifest.json`);

    const manifest: Manifest = JSON.parse(manifestJson);

    return {
      manifest,
      intent: {
        original_request: "",
        dead_ends: [],
        decisions: [],
      },
      transcript: { entries: [] },
      operations: { tool_calls: [], file_changes: [], shell_commands: [] },
      lineage: { child_engrams: [], related_engrams: [], git_commits: manifest.git_commits || [] },
    };
  }

  /**
   * Read only the manifest (fast path).
   */
  readManifest(idOrPrefix: string): Manifest {
    return this.read(idOrPrefix).manifest;
  }

  /**
   * List all engrams, most recent first.
   */
  list(): Manifest[] {
    let output: string;
    try {
      output = gitCmd(
        this.repoPath,
        `for-each-ref --format="%(refname)" refs/engrams/`,
      );
    } catch {
      return [];
    }

    if (!output.trim()) return [];

    const manifests: Manifest[] = [];
    for (const ref of output.split("\n")) {
      if (!ref.trim()) continue;
      try {
        const commitOid = gitCmd(this.repoPath, `rev-parse ${ref}`);
        const treeOid = gitCmd(this.repoPath, `rev-parse ${commitOid}^{tree}`);
        const manifestJson = gitCmd(this.repoPath, `cat-file blob ${treeOid}:manifest.json`);
        manifests.push(JSON.parse(manifestJson));
      } catch {
        continue;
      }
    }

    manifests.sort(
      (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
    );

    return manifests;
  }

  /**
   * Delete an engram by removing its ref.
   */
  delete(idOrPrefix: string): void {
    const resolvedRef = this.resolve(idOrPrefix);
    gitCmd(this.repoPath, `update-ref -d ${resolvedRef}`);
  }

  private resolve(idOrPrefix: string): string {
    // Try exact match
    const exactRef = refName(idOrPrefix);
    try {
      gitCmd(this.repoPath, `rev-parse --verify ${exactRef}`);
      return exactRef;
    } catch {
      // fall through
    }

    // Try prefix match
    let output: string;
    try {
      output = gitCmd(
        this.repoPath,
        `for-each-ref --format="%(refname)" refs/engrams/`,
      );
    } catch {
      throw new Error(`Engram not found: ${idOrPrefix}`);
    }

    const matches: string[] = [];
    for (const ref of output.split("\n")) {
      if (!ref.trim()) continue;
      const parts = ref.replace(ENGRAM_REF_PREFIX, "").split("/");
      if (parts.length === 2 && parts[1].startsWith(idOrPrefix)) {
        matches.push(ref);
      }
    }

    if (matches.length === 0) {
      throw new Error(`Engram not found: ${idOrPrefix}`);
    }
    if (matches.length > 1) {
      throw new Error(`Ambiguous engram prefix: ${idOrPrefix} (${matches.length} matches)`);
    }

    return matches[0];
  }
}

/**
 * Fluent session builder for creating engrams programmatically.
 */

import type {
  AgentInfo,
  DeadEnd,
  Decision,
  EngramData,
  FileChange,
  ShellCommand,
  TokenUsage,
  ToolCall,
  TranscriptEntry,
} from "./model.js";
import { defaultTokenUsage, newEngramId } from "./model.js";
import { GitStorage } from "./storage.js";

const CHANGE_TYPE_MAP: Record<string, string> = {
  created: "Created",
  create: "Created",
  new: "Created",
  modified: "Modified",
  modify: "Modified",
  changed: "Modified",
  deleted: "Deleted",
  delete: "Deleted",
  removed: "Deleted",
};

export class EngramSession {
  private agent: AgentInfo;
  private _transcript: TranscriptEntry[] = [];
  private _toolCalls: ToolCall[] = [];
  private _fileChanges: FileChange[] = [];
  private _shellCommands: ShellCommand[] = [];
  private _deadEnds: DeadEnd[] = [];
  private _decisions: Decision[] = [];
  private _tokenUsage: TokenUsage;
  private _originalRequest?: string;
  private _summary?: string;
  private _tags: string[] = [];
  private _parent?: string;
  private _startedAt: string;

  private constructor(agentName: string, model?: string) {
    this.agent = { name: agentName, model };
    this._tokenUsage = defaultTokenUsage();
    this._startedAt = new Date().toISOString();
  }

  /**
   * Create a new session for a given agent and optional model.
   */
  static begin(agentName: string, model?: string): EngramSession {
    return new EngramSession(agentName, model);
  }

  /**
   * Log a message (user, assistant, system, or tool).
   */
  logMessage(role: string, content: string): EngramSession {
    if (role === "user" && this._originalRequest === undefined) {
      this._originalRequest = content;
    }

    this._transcript.push({
      timestamp: new Date().toISOString(),
      role,
      content: { type: "text", text: content },
    });
    return this;
  }

  /**
   * Log a tool call.
   */
  logToolCall(
    toolName: string,
    input: string | Record<string, unknown>,
    outputSummary?: string,
  ): EngramSession {
    let parsedInput: unknown;
    if (typeof input === "string") {
      try {
        parsedInput = JSON.parse(input);
      } catch {
        parsedInput = input;
      }
    } else {
      parsedInput = input;
    }

    this._toolCalls.push({
      timestamp: new Date().toISOString(),
      tool_name: toolName,
      input: parsedInput,
      output_summary: outputSummary,
      is_error: false,
    });
    return this;
  }

  /**
   * Log a file change.
   */
  logFileChange(path: string, changeType: string): EngramSession {
    const ct = CHANGE_TYPE_MAP[changeType.toLowerCase()] || "Modified";
    this._fileChanges.push({ path, change_type: ct });
    return this;
  }

  /**
   * Log a shell command execution.
   */
  logShellCommand(
    command: string,
    exitCode?: number,
    durationMs?: number,
  ): EngramSession {
    this._shellCommands.push({
      timestamp: new Date().toISOString(),
      command,
      exit_code: exitCode,
      duration_ms: durationMs,
    });
    return this;
  }

  /**
   * Log a rejected approach (dead end).
   */
  logRejection(approach: string, reason: string): EngramSession {
    this._deadEnds.push({ approach, reason });
    return this;
  }

  /**
   * Log a decision made during the session.
   */
  logDecision(description: string, rationale: string): EngramSession {
    this._decisions.push({ description, rationale });
    return this;
  }

  /**
   * Add token usage. Accumulates across multiple calls.
   */
  addTokens(
    inputTokens: number,
    outputTokens: number,
    costUsd?: number,
  ): EngramSession {
    this._tokenUsage.input_tokens += inputTokens;
    this._tokenUsage.output_tokens += outputTokens;
    this._tokenUsage.total_tokens += inputTokens + outputTokens;
    if (costUsd !== undefined) {
      this._tokenUsage.cost_usd = (this._tokenUsage.cost_usd || 0) + costUsd;
    }
    return this;
  }

  /**
   * Set a summary for this session.
   */
  setSummary(summary: string): EngramSession {
    this._summary = summary;
    return this;
  }

  /**
   * Add a tag.
   */
  tag(tagName: string): EngramSession {
    this._tags.push(tagName);
    return this;
  }

  /**
   * Set the parent engram ID.
   */
  parent(parentId: string): EngramSession {
    this._parent = parentId;
    return this;
  }

  /**
   * Build the EngramData without storing it.
   */
  build(gitSha?: string, summary?: string): EngramData {
    const engramId = newEngramId();
    const finishedAt = new Date().toISOString();
    const finalSummary = summary || this._summary || this._originalRequest;
    const gitCommits = gitSha ? [gitSha] : [];

    return {
      manifest: {
        id: engramId,
        version: 1,
        created_at: this._startedAt,
        finished_at: finishedAt,
        agent: this.agent,
        git_commits: gitCommits,
        token_usage: this._tokenUsage,
        summary: finalSummary,
        tags: this._tags,
        capture_mode: "Sdk",
      },
      intent: {
        original_request: this._originalRequest || "SDK session",
        summary: finalSummary,
        dead_ends: this._deadEnds,
        decisions: this._decisions,
      },
      transcript: {
        entries: this._transcript,
      },
      operations: {
        tool_calls: this._toolCalls,
        file_changes: this._fileChanges,
        shell_commands: this._shellCommands,
      },
      lineage: {
        parent_engram: this._parent,
        child_engrams: [],
        related_engrams: [],
        git_commits: gitCommits,
      },
    };
  }

  /**
   * Finalize and store the engram in Git. Returns the engram ID.
   */
  commit(gitSha?: string, summary?: string, storage?: GitStorage): string {
    const data = this.build(gitSha, summary);
    const store = storage || GitStorage.discover();
    return store.create(data);
  }
}

