 52→impl Transcript {
 53→    /// Serialize to JSONL bytes (one JSON object per line).
 54→    pub fn to_jsonl(&self) -> Vec<u8> {
 55→        let mut buf = Vec::new();
 56→        for entry in &self.entries {
 57→            if !buf.is_empty() {
 58→                // entries after the first get a newline prefix
 59→            }
 60→            serde_json::to_writer(&mut buf, entry).expect("transcript entry serialization");
 61→            buf.push(b'\n');
 62→        }
 63→        buf
 64→    }
