 66→    /// Deserialize from JSONL bytes.
 67→    pub fn from_jsonl(data: &[u8]) -> Result<Self, CoreError> {
 68→        let text = std::str::from_utf8(data).map_err(|e| CoreError::Parse(e.to_string()))?;
