 70→        for line in text.lines() {
 71→            if line.trim().is_empty() {
 72→                continue;
 73→            }
 74→            let entry: TranscriptEntry =
 75→                serde_json::from_str(line).map_err(CoreError::InvalidManifest)?;
 76→            entries.push(entry);
 77→        }
 78→        Ok(Transcript { entries })
 79→    }
