  6→/// Build the engram tree object from EngramData.
  7→///
  8→/// Creates blobs for each file, inserts them into a TreeBuilder, writes the tree,
  9→/// then creates a commit pointing to that tree. Returns the commit Oid.
 10→///
 11→/// Object layout:
 12→///   commit (message = "engram: {id}")
 13→///     -> tree
 14→///        -> blob "manifest.json"
 15→///        -> blob "intent.md"
 16→///        -> blob "transcript.jsonl"
 17→///        -> blob "operations.json"
 18→///        -> blob "lineage.json"
 19→pub fn create_engram_objects(repo: &Repository, data: &EngramData) -> Result<Oid, CoreError> {
 20→    // 1. Serialize each component to bytes
 21→    let manifest_bytes = serde_json::to_vec_pretty(&data.manifest)?;
 22→    let intent_bytes = data.intent.to_markdown().into_bytes();
 23→    let transcript_bytes = data.transcript.to_jsonl();
 24→    let operations_bytes = serde_json::to_vec_pretty(&data.operations)?;
 25→    let lineage_bytes = serde_json::to_vec_pretty(&data.lineage)?;
 26→
 27→    // 2. Create blobs
 28→    let manifest_oid = repo.blob(&manifest_bytes)?;
 29→    let intent_oid = repo.blob(&intent_bytes)?;
 30→    let transcript_oid = repo.blob(&transcript_bytes)?;
 31→    let operations_oid = repo.blob(&operations_bytes)?;
 32→    let lineage_oid = repo.blob(&lineage_bytes)?;
 33→
 34→    // 3. Build tree
 35→    let mut builder = repo.treebuilder(None)?;
 36→    builder.insert("manifest.json", manifest_oid, 0o100644)?;
 37→    builder.insert("intent.md", intent_oid, 0o100644)?;
 38→    builder.insert("transcript.jsonl", transcript_oid, 0o100644)?;
 39→    builder.insert("operations.json", operations_oid, 0o100644)?;
 40→    builder.insert("lineage.json", lineage_oid, 0o100644)?;
 41→    let tree_oid = builder.write()?;
 42→
 43→    // 4. Create commit (no parent — standalone orphan)
 44→    let tree = repo.find_tree(tree_oid)?;
 45→    let sig = Signature::now("engram", "engram@local")?;
 46→    let message = format!("engram: {}", data.manifest.id);
 47→    let commit_oid = repo.commit(None, &sig, &sig, &message, &tree, &[])?;
 48→
 49→    Ok(commit_oid)
 50→}
