123→        assert_eq!(refs.len(), 2);
124→
125→        // Delete
126→        delete_engram_ref(&repo, &id1).unwrap();
127→        let refs = list_engram_refs(&repo).unwrap();
128→        assert_eq!(refs.len(), 1);
129→        assert_eq!(refs[0].0, id2);
130→    }
131→
132→    #[test]
133→    fn test_resolve_prefix() {
134→        let tmp = TempDir::new().unwrap();
135→        let repo = Repository::init(tmp.path()).unwrap();
136→
137→        let blob_oid = repo.blob(b"test").unwrap();
138→        let mut tb = repo.treebuilder(None).unwrap();
139→        tb.insert("test", blob_oid, 0o100644).unwrap();
140→        let tree_oid = tb.write().unwrap();
141→        let tree = repo.find_tree(tree_oid).unwrap();
142→        let sig = git2::Signature::now("test", "test@test").unwrap();
143→        let commit_oid = repo.commit(None, &sig, &sig, "test", &tree, &[]).unwrap();
144→
145→        let id = EngramId("abcdef1234567890abcdef1234567890".into());
146→        create_engram_ref(&repo, &id, commit_oid).unwrap();
147→
148→        // Full match
149→        let (resolved, _) = resolve_engram_ref(&repo, "abcdef1234567890abcdef1234567890").unwrap();
150→        assert_eq!(resolved, id);
151→
152→        // Prefix match
153→        let (resolved, _) = resolve_engram_ref(&repo, "abcdef").unwrap();
154→        assert_eq!(resolved, id);
155→
156→        // Not found
157→        assert!(resolve_engram_ref(&repo, "zzzzz").is_err());
