  1→use serde::{Deserialize, Serialize};
  2→
  3→use crate::error::CoreError;
  4→
  5→/// Structured intent data, stored as intent.md (Markdown) in the engram tree.
  6→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
  7→pub struct Intent {
  8→    pub original_request: String,
  9→    #[serde(default, skip_serializing_if = "Option::is_none")]
 10→    pub interpreted_goal: Option<String>,
 11→    #[serde(default, skip_serializing_if = "Option::is_none")]
 12→    pub summary: Option<String>,
 13→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 14→    pub dead_ends: Vec<DeadEnd>,
 15→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 16→    pub decisions: Vec<Decision>,
 17→}
 18→
 19→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
 20→pub struct DeadEnd {
 21→    pub approach: String,
 22→    pub reason: String,
 23→}
 24→
 25→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
 26→pub struct Decision {
 27→    pub description: String,
 28→    pub rationale: String,
 29→}
 30→
 31→impl Intent {
 32→    /// Render as Markdown for storage as intent.md
 33→    pub fn to_markdown(&self) -> String {
 34→        let mut md = String::new();
 35→
 36→        md.push_str("# Intent\n\n");
 37→        md.push_str(&self.original_request);
 38→        md.push('\n');
 39→
 40→        if let Some(goal) = &self.interpreted_goal {
 41→            md.push_str("\n## Interpreted Goal\n\n");
 42→            md.push_str(goal);
 43→            md.push('\n');
 44→        }
 45→
 46→        if let Some(summary) = &self.summary {
 47→            md.push_str("\n## Summary\n\n");
 48→            md.push_str(summary);
 49→            md.push('\n');
 50→        }
 51→
 52→        if !self.dead_ends.is_empty() {
 53→            md.push_str("\n## Dead Ends\n\n");
 54→            for de in &self.dead_ends {
 55→                md.push_str(&format!("- **{}**: {}\n", de.approach, de.reason));
 56→            }
 57→        }
 58→
 59→        if !self.decisions.is_empty() {
 60→            md.push_str("\n## Decisions\n\n");
 61→            for d in &self.decisions {
 62→                md.push_str(&format!("- **{}**: {}\n", d.description, d.rationale));
 63→            }
 64→        }
 65→
 66→        md
 67→    }
 68→
 69→    /// Parse from Markdown
 70→    pub fn from_markdown(md: &str) -> Result<Self, CoreError> {
 71→        let mut original_request = String::new();
 72→        let mut interpreted_goal = None;
 73→        let mut summary = None;
 74→        let mut dead_ends = Vec::new();
 75→        let mut decisions = Vec::new();
 76→
 77→        let mut current_section = "intent";
 78→        let mut current_content = String::new();
 79→
 80→        for line in md.lines() {
 81→            if line.starts_with("# Intent") {
 82→                current_section = "intent";
 83→                current_content.clear();
 84→                continue;
 85→            } else if line.starts_with("## Interpreted Goal") {
 86→                // Save previous section
 87→                Self::save_section(
 88→                    current_section,
 89→                    &current_content,
 90→                    &mut original_request,
 91→                    &mut interpreted_goal,
 92→                    &mut summary,
 93→                );
 94→                current_section = "goal";
 95→                current_content.clear();
 96→                continue;
 97→            } else if line.starts_with("## Summary") {
 98→                Self::save_section(
 99→                    current_section,
100→                    &current_content,
101→                    &mut original_request,
102→                    &mut interpreted_goal,
103→                    &mut summary,
104→                );
105→                current_section = "summary";
106→                current_content.clear();
107→                continue;
108→            } else if line.starts_with("## Dead Ends") {
109→                Self::save_section(
110→                    current_section,
111→                    &current_content,
112→                    &mut original_request,
113→                    &mut interpreted_goal,
114→                    &mut summary,
115→                );
116→                current_section = "dead_ends";
117→                current_content.clear();
118→                continue;
119→            } else if line.starts_with("## Decisions") {
120→                Self::save_section(
121→                    current_section,
122→                    &current_content,
123→                    &mut original_request,
124→                    &mut interpreted_goal,
125→                    &mut summary,
126→                );
127→                current_section = "decisions";
128→                current_content.clear();
129→                continue;
130→            }
131→
132→            match current_section {
133→                "dead_ends" => {
134→                    if let Some(entry) = line.strip_prefix("- **") {
135→                        if let Some((approach, reason)) = entry.split_once("**: ") {
136→                            dead_ends.push(DeadEnd {
137→                                approach: approach.to_string(),
138→                                reason: reason.to_string(),
139→                            });
140→                        }
141→                    }
142→                }
143→                "decisions" => {
144→                    if let Some(entry) = line.strip_prefix("- **") {
145→                        if let Some((desc, rationale)) = entry.split_once("**: ") {
146→                            decisions.push(Decision {
147→                                description: desc.to_string(),
148→                                rationale: rationale.to_string(),
149→                            });
150→                        }
151→                    }
152→                }
153→                _ => {
154→                    if !current_content.is_empty() || !line.is_empty() {
155→                        if !current_content.is_empty() {
156→                            current_content.push('\n');
157→                        }
158→                        current_content.push_str(line);
159→                    }
160→                }
161→            }
162→        }
163→
164→        // Save last section
165→        Self::save_section(
166→            current_section,
167→            &current_content,
168→            &mut original_request,
169→            &mut interpreted_goal,
170→            &mut summary,
171→        );
172→
173→        Ok(Intent {
174→            original_request,
175→            interpreted_goal,
176→            summary,
177→            dead_ends,
178→            decisions,
179→        })
180→    }
181→
182→    fn save_section(
183→        section: &str,
184→        content: &str,
185→        original_request: &mut String,
186→        interpreted_goal: &mut Option<String>,
187→        summary: &mut Option<String>,
188→    ) {
189→        let trimmed = content.trim().to_string();
190→        if trimmed.is_empty() {
191→            return;
192→        }
193→        match section {
194→            "intent" => *original_request = trimmed,
195→            "goal" => *interpreted_goal = Some(trimmed),
196→            "summary" => *summary = Some(trimmed),
197→            _ => {}
198→        }
199→    }
200→}
201→
