  1→/**
  2→ * Git-native storage for engrams using git CLI commands (via simple-git).
  3→ */
  4→
  5→import { execSync } from "child_process";
  6→import { readFileSync, readdirSync, statSync } from "fs";
  7→import { join } from "path";
  8→import type { EngramData, Manifest } from "./model.js";
  9→import { intentToMarkdown, transcriptToJsonl } from "./model.js";
 10→
 11→const ENGRAM_REF_PREFIX = "refs/engrams/";
 12→
 13→function refName(engramId: string): string {
 14→  const prefix = engramId.slice(0, 2);
 15→  return `refs/engrams/${prefix}/${engramId}`;
 16→}
 17→
 18→function gitCmd(repoPath: string, args: string, input?: string): string {
 19→  const opts: Parameters<typeof execSync>[1] = {
 20→    cwd: repoPath,
 21→    encoding: "utf-8" as const,
 22→    maxBuffer: 50 * 1024 * 1024,
 23→    stdio: input ? ["pipe", "pipe", "pipe"] : ["pipe", "pipe", "pipe"],
 24→  };
 25→  if (input) {
 26→    (opts as Record<string, unknown>).input = input;
 27→  }
 28→  return execSync(`git ${args}`, opts).toString().trim();
 29→}
 30→
 31→export class GitStorage {
 32→  private repoPath: string;
 33→
 34→  constructor(repoPath: string) {
 35→    this.repoPath = repoPath;
 36→  }
 37→
 38→  static open(path: string): GitStorage {
 39→    return new GitStorage(path);
 40→  }
 41→
 42→  static discover(startPath: string = "."): GitStorage {
 43→    const toplevel = execSync("git rev-parse --show-toplevel", {
 44→      cwd: startPath,
 45→      encoding: "utf-8",
 46→    }).trim();
 47→    return new GitStorage(toplevel);
 48→  }
 49→
 50→  /**
 51→   * Store an engram as Git objects and create a ref. Returns the engram ID.
 52→   */
 53→  create(data: EngramData): string {
 54→    const manifestJson = JSON.stringify(data.manifest, null, 2);
 55→    const intentMd = intentToMarkdown(data.intent);
 56→    const transcriptJsonl = transcriptToJsonl(data.transcript);
 57→    const operationsJson = JSON.stringify(data.operations, null, 2);
 58→    const lineageJson = JSON.stringify(data.lineage, null, 2);
 59→
 60→    // Create blobs
 61→    const manifestOid = gitCmd(this.repoPath, "hash-object -w --stdin", manifestJson);
 62→    const intentOid = gitCmd(this.repoPath, "hash-object -w --stdin", intentMd);
 63→    const transcriptOid = gitCmd(this.repoPath, "hash-object -w --stdin", transcriptJsonl);
 64→    const operationsOid = gitCmd(this.repoPath, "hash-object -w --stdin", operationsJson);
 65→    const lineageOid = gitCmd(this.repoPath, "hash-object -w --stdin", lineageJson);
 66→
 67→    // Build tree via mktree
 68→    const treeInput = [
 69→      `100644 blob ${intentOid}\tintent.md`,
 70→      `100644 blob ${lineageOid}\tlineage.json`,
 71→      `100644 blob ${manifestOid}\tmanifest.json`,
 72→      `100644 blob ${operationsOid}\toperations.json`,
 73→      `100644 blob ${transcriptOid}\ttranscript.jsonl`,
 74→    ].join("\n");
 75→
 76→    const treeOid = gitCmd(this.repoPath, "mktree", treeInput);
 77→
 78→    // Create commit
 79→    const summary = data.manifest.summary || "engram session";
 80→    const commitOid = gitCmd(
 81→      this.repoPath,
 82→      `commit-tree ${treeOid} -m "engram: ${summary}"`,
 83→    );
 84→
 85→    // Create ref
 86→    const ref = refName(data.manifest.id);
 87→    gitCmd(this.repoPath, `update-ref ${ref} ${commitOid}`);
 88→
 89→    return data.manifest.id;
 90→  }
 91→
 92→  /**
 93→   * Read an engram by its ID (or prefix).
 94→   */
 95→  read(idOrPrefix: string): EngramData {
 96→    const resolvedRef = this.resolve(idOrPrefix);
 97→    const commitOid = gitCmd(this.repoPath, `rev-parse ${resolvedRef}`);
 98→
 99→    // Get tree from commit
100→    const treeOid = gitCmd(this.repoPath, `rev-parse ${commitOid}^{tree}`);
101→
102→    // Read each blob
103→    const manifestJson = gitCmd(this.repoPath, `cat-file blob ${treeOid}:manifest.json`);
104→
105→    const manifest: Manifest = JSON.parse(manifestJson);
106→
107→    return {
108→      manifest,
109→      intent: {
110→        original_request: "",
111→        dead_ends: [],
112→        decisions: [],
113→      },
114→      transcript: { entries: [] },
115→      operations: { tool_calls: [], file_changes: [], shell_commands: [] },
116→      lineage: { child_engrams: [], related_engrams: [], git_commits: manifest.git_commits || [] },
117→    };
118→  }
119→
120→  /**
121→   * Read only the manifest (fast path).
122→   */
123→  readManifest(idOrPrefix: string): Manifest {
124→    return this.read(idOrPrefix).manifest;
125→  }
126→
127→  /**
128→   * List all engrams, most recent first.
129→   */
130→  list(): Manifest[] {
131→    let output: string;
132→    try {
133→      output = gitCmd(
134→        this.repoPath,
135→        `for-each-ref --format="%(refname)" refs/engrams/`,
136→      );
137→    } catch {
138→      return [];
139→    }
140→
141→    if (!output.trim()) return [];
142→
143→    const manifests: Manifest[] = [];
144→    for (const ref of output.split("\n")) {
145→      if (!ref.trim()) continue;
146→      try {
147→        const commitOid = gitCmd(this.repoPath, `rev-parse ${ref}`);
148→        const treeOid = gitCmd(this.repoPath, `rev-parse ${commitOid}^{tree}`);
149→        const manifestJson = gitCmd(this.repoPath, `cat-file blob ${treeOid}:manifest.json`);
150→        manifests.push(JSON.parse(manifestJson));
151→      } catch {
152→        continue;
153→      }
154→    }
155→
156→    manifests.sort(
157→      (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
158→    );
159→
160→    return manifests;
161→  }
162→
163→  /**
164→   * Delete an engram by removing its ref.
165→   */
166→  delete(idOrPrefix: string): void {
167→    const resolvedRef = this.resolve(idOrPrefix);
168→    gitCmd(this.repoPath, `update-ref -d ${resolvedRef}`);
169→  }
170→
171→  private resolve(idOrPrefix: string): string {
172→    // Try exact match
173→    const exactRef = refName(idOrPrefix);
174→    try {
175→      gitCmd(this.repoPath, `rev-parse --verify ${exactRef}`);
176→      return exactRef;
177→    } catch {
178→      // fall through
179→    }
180→
181→    // Try prefix match
182→    let output: string;
183→    try {
184→      output = gitCmd(
185→        this.repoPath,
186→        `for-each-ref --format="%(refname)" refs/engrams/`,
187→      );
188→    } catch {
189→      throw new Error(`Engram not found: ${idOrPrefix}`);
190→    }
191→
192→    const matches: string[] = [];
193→    for (const ref of output.split("\n")) {
194→      if (!ref.trim()) continue;
195→      const parts = ref.replace(ENGRAM_REF_PREFIX, "").split("/");
196→      if (parts.length === 2 && parts[1].startsWith(idOrPrefix)) {
197→        matches.push(ref);
198→      }
199→    }
200→
201→    if (matches.length === 0) {
202→      throw new Error(`Engram not found: ${idOrPrefix}`);
203→    }
204→    if (matches.length > 1) {
205→      throw new Error(`Ambiguous engram prefix: ${idOrPrefix} (${matches.length} matches)`);
206→    }
207→
208→    return matches[0];
209→  }
210→}
