127→export function intentToMarkdown(intent: Intent): string {
128→  const lines: string[] = [
129→    "# Intent",
130→    "",
131→    "## Original Request",
132→    "",
133→    intent.original_request,
134→    "",
135→  ];
136→
137→  if (intent.summary) {
138→    lines.push("## Summary", "", intent.summary, "");
139→  }
140→
141→  if (intent.dead_ends.length > 0) {
142→    lines.push("## Dead Ends", "");
143→    for (const de of intent.dead_ends) {
144→      lines.push(`- **${de.approach}**: ${de.reason}`);
145→    }
146→    lines.push("");
147→  }
148→
149→  if (intent.decisions.length > 0) {
150→    lines.push("## Decisions", "");
151→    for (const d of intent.decisions) {
152→      lines.push(`- **${d.description}**: ${d.rationale}`);
153→    }
154→    lines.push("");
155→  }
156→
157→  return lines.join("\n");
158→}
