 30→
 31→export class EngramSession {
 32→  private agent: AgentInfo;
 33→  private _transcript: TranscriptEntry[] = [];
 34→  private _toolCalls: ToolCall[] = [];
 35→  private _fileChanges: FileChange[] = [];
 36→  private _shellCommands: ShellCommand[] = [];
 37→  private _deadEnds: DeadEnd[] = [];
 38→  private _decisions: Decision[] = [];
