  9→/// Snapshot the working tree: map of relative path -> SHA256 hash.
 10→/// Ignores .git directory and common build artifacts.
 11→pub fn snapshot_working_tree(
 12→    repo_root: &Path,
 13→) -> Result<HashMap<PathBuf, Vec<u8>>, std::io::Error> {
 14→    let mut snapshot = HashMap::new();
 15→
 16→    for entry in WalkDir::new(repo_root)
 17→        .into_iter()
 18→        .filter_entry(|e| !is_ignored(e.path(), repo_root))
 19→    {
 20→        let entry = entry?;
 21→        if !entry.file_type().is_file() {
 22→            continue;
 23→        }
 24→        let rel_path = entry
 25→            .path()
 26→            .strip_prefix(repo_root)
 27→            .unwrap_or(entry.path())
 28→            .to_path_buf();
 29→
 30→        match std::fs::read(entry.path()) {
 31→            Ok(contents) => {
 32→                let hash = Sha256::digest(&contents).to_vec();
 33→                snapshot.insert(rel_path, hash);
 34→            }
 35→            Err(e) => {
 36→                tracing::debug!("Skipping unreadable file {:?}: {}", entry.path(), e);
 37→            }
 38→        }
 39→    }
 40→
 41→    Ok(snapshot)
 42→}
