 44→/// Compare before/after snapshots to detect file changes.
 45→pub fn detect_changes(
 46→    before: &HashMap<PathBuf, Vec<u8>>,
 47→    after: &HashMap<PathBuf, Vec<u8>>,
 48→) -> Vec<FileChange> {
 49→    let mut changes = Vec::new();
 50→
 51→    // Check for created and modified files
 52→    for (path, after_hash) in after {
 53→        match before.get(path) {
 54→            None => {
 55→                changes.push(FileChange {
 56→                    path: path.to_string_lossy().to_string(),
 57→                    change_type: FileChangeType::Created,
 58→                    lines_added: None,
 59→                    lines_removed: None,
 60→                });
 61→            }
 62→            Some(before_hash) if before_hash != after_hash => {
 63→                changes.push(FileChange {
 64→                    path: path.to_string_lossy().to_string(),
 65→                    change_type: FileChangeType::Modified,
 66→                    lines_added: None,
 67→                    lines_removed: None,
 68→                });
 69→            }
 70→            _ => {} // Unchanged
 71→        }
 72→    }
 73→
 74→    // Check for deleted files
 75→    for path in before.keys() {
 76→        if !after.contains_key(path) {
 77→            changes.push(FileChange {
 78→                path: path.to_string_lossy().to_string(),
 79→                change_type: FileChangeType::Deleted,
 80→                lines_added: None,
 81→                lines_removed: None,
 82→            });
 83→        }
 84→    }
 85→
 86→    // Sort for deterministic output
 87→    changes.sort_by(|a, b| a.path.cmp(&b.path));
