114→
115→        // Create initial files
116→        std::fs::write(root.join("existing.txt"), "hello").unwrap();
117→        std::fs::write(root.join("to_delete.txt"), "goodbye").unwrap();
118→        std::fs::write(root.join("unchanged.txt"), "same").unwrap();
119→
120→        let before = snapshot_working_tree(root).unwrap();
121→        assert_eq!(before.len(), 3);
122→
