 13→/// Options for listing engrams.
 14→#[derive(Debug, Clone, Default)]
 15→pub struct ListOptions {
 16→    pub limit: Option<usize>,
 17→    pub agent_filter: Option<String>,
 18→}
 19→
 20→/// The main storage interface for engram operations.
 21→pub struct GitStorage {
 22→    repo: Repository,
 23→}
 24→
 25→impl GitStorage {
 26→    /// Open the Git repository at the given path.
 27→    pub fn open(path: &Path) -> Result<Self, CoreError> {
 28→        let repo = Repository::open(path)?;
 29→        Ok(Self { repo })
 30→    }
 31→
 32→    /// Discover the Git repository from the current directory.
 33→    pub fn discover() -> Result<Self, CoreError> {
 34→        let repo = Repository::discover(".")?;
 35→        Ok(Self { repo })
 36→    }
 37→
 38→    /// Check if engram has been initialized in this repo.
 39→    pub fn is_initialized(&self) -> bool {
 40→        self.repo
 41→            .config()
 42→            .ok()
 43→            .and_then(|c| c.get_bool("engram.enabled").ok())
 44→            .unwrap_or(false)
 45→    }
 46→
 47→    /// Initialize engram in this repo: set config, configure refspecs.
 48→    /// If `remote` is Some, only configure that specific remote; otherwise configure all.
 49→    pub fn init_with_remote(&self, remote: Option<&str>) -> Result<(), CoreError> {
 50→        let mut config = self.repo.config().map_err(CoreError::Git)?;
 51→        let engram_config = EngramConfig::default_init();
 52→        engram_config.save(&mut config)?;
 53→
 54→        // Set schema version
 55→        config
 56→            .set_i32("engram.version", 1)
 57→            .map_err(CoreError::Git)?;
 58→
 59→        // Add engram fetch/push refspecs to remotes
 60→        self.configure_remotes_filtered(remote)?;
 61→
 62→        Ok(())
 63→    }
 64→
 65→    /// Initialize engram in this repo: set config, configure refspecs on all remotes.
 66→    pub fn init(&self) -> Result<(), CoreError> {
 67→        self.init_with_remote(None)
 68→    }
 69→
 70→    /// Create a new engram and store it as Git objects.
 71→    pub fn create(&self, data: &EngramData) -> Result<EngramId, CoreError> {
 72→        let commit_oid = create_engram_objects(&self.repo, data)?;
 73→        let id = data.manifest.id.clone();
 74→        refs::create_engram_ref(&self.repo, &id, commit_oid)?;
 75→        Ok(id)
 76→    }
 77→
 78→    /// Resolve "HEAD" to the most recent engram ID, or pass through to prefix resolution.
 79→    pub fn resolve(&self, id_or_alias: &str) -> Result<String, CoreError> {
 80→        if id_or_alias.eq_ignore_ascii_case("HEAD") {
 81→            let manifests = self.list(&ListOptions::default())?;
 82→            if let Some(m) = manifests.first() {
 83→                Ok(m.id.as_str().to_string())
 84→            } else {
 85→                Err(CoreError::NotFound {
 86→                    id: "HEAD (no engrams exist)".to_string(),
 87→                })
 88→            }
 89→        } else {
 90→            let (id, _oid) = refs::resolve_engram_ref(&self.repo, id_or_alias)?;
 91→            Ok(id.as_str().to_string())
 92→        }
 93→    }
 94→
 95→    /// Read an engram by its ID (or prefix).
 96→    pub fn read(&self, id_or_prefix: &str) -> Result<EngramData, CoreError> {
 97→        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
 98→        read::read_engram(&self.repo, oid)
 99→    }
100→
101→    /// Read only the manifest (fast path for listing).
102→    pub fn read_manifest(&self, id_or_prefix: &str) -> Result<Manifest, CoreError> {
103→        let (_id, oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
104→        read::read_manifest(&self.repo, oid)
105→    }
106→
107→    /// List all engrams, optionally filtered.
108→    pub fn list(&self, opts: &ListOptions) -> Result<Vec<Manifest>, CoreError> {
109→        let all_refs = refs::list_engram_refs(&self.repo)?;
110→        let mut manifests = Vec::with_capacity(all_refs.len());
111→
112→        for (_id, oid) in &all_refs {
113→            match read::read_manifest(&self.repo, *oid) {
114→                Ok(manifest) => {
115→                    // Apply agent filter
116→                    if let Some(agent) = &opts.agent_filter {
117→                        if !manifest.agent.name.contains(agent.as_str()) {
118→                            continue;
119→                        }
120→                    }
121→                    manifests.push(manifest);
122→                }
123→                Err(e) => {
124→                    tracing::warn!("Skipping unreadable engram: {e}");
125→                }
126→            }
127→        }
128→
129→        // Sort by created_at descending (most recent first)
130→        manifests.sort_by(|a, b| b.created_at.cmp(&a.created_at));
131→
132→        // Apply limit
133→        if let Some(limit) = opts.limit {
134→            manifests.truncate(limit);
135→        }
136→
137→        Ok(manifests)
138→    }
139→
140→    /// Delete an engram by removing its ref.
141→    pub fn delete(&self, id_or_prefix: &str) -> Result<(), CoreError> {
142→        let (id, _oid) = refs::resolve_engram_ref(&self.repo, id_or_prefix)?;
143→        refs::delete_engram_ref(&self.repo, &id)
144→    }
145→
146→    /// Get the underlying git2::Repository reference.
147→    pub fn repo(&self) -> &Repository {
148→        &self.repo
149→    }
150→
151→    /// Get the repo working directory path.
152→    pub fn workdir(&self) -> Option<&Path> {
153→        self.repo.workdir()
154→    }
155→
156→    /// Configure fetch/push refspecs for engram refs on remotes.
157→    /// If `filter` is Some, only configure that specific remote.
158→    fn configure_remotes_filtered(&self, filter: Option<&str>) -> Result<(), CoreError> {
159→        let remotes = self.repo.remotes().map_err(CoreError::Git)?;
160→        let mut config = self.repo.config().map_err(CoreError::Git)?;
161→
162→        for remote_name in remotes.iter().flatten() {
163→            if let Some(target) = filter {
164→                if remote_name != target {
165→                    continue;
166→                }
167→            }
168→            let fetch_key = format!("remote.{remote_name}.fetch");
169→            let push_key = format!("remote.{remote_name}.push");
170→            let fetch_refspec = "+refs/engrams/*:refs/engrams/*";
171→            let push_refspec = "refs/engrams/*:refs/engrams/*";
172→
173→            // Check if already configured by iterating existing values
174→            let fetch_exists = config
175→                .entries(Some(&fetch_key))
176→                .ok()
177→                .map(|mut entries| {
178→                    let mut found = false;
179→                    while let Some(Ok(entry)) = entries.next() {
180→                        if entry.value() == Some(fetch_refspec) {
181→                            found = true;
182→                            break;
183→                        }
184→                    }
185→                    found
186→                })
187→                .unwrap_or(false);
188→
189→            if !fetch_exists {
190→                config
191→                    .set_multivar(&fetch_key, "^$", fetch_refspec)
192→                    .or_else(|_| {
193→                        // If set_multivar fails (no existing entry), try adding
194→                        self.repo
195→                            .remote_add_fetch(remote_name, fetch_refspec)
196→                            .map(|_| ())
197→                    })
198→                    .map_err(CoreError::Git)?;
199→            }
200→
201→            let push_exists = config
202→                .entries(Some(&push_key))
203→                .ok()
204→                .map(|mut entries| {
205→                    let mut found = false;
206→                    while let Some(Ok(entry)) = entries.next() {
207→                        if entry.value() == Some(push_refspec) {
208→                            found = true;
209→                            break;
210→                        }
211→                    }
212→                    found
213→                })
214→                .unwrap_or(false);
215→
216→            if !push_exists {
217→                config
218→                    .set_multivar(&push_key, "^$", push_refspec)
219→                    .or_else(|_| {
220→                        self.repo
221→                            .remote_add_push(remote_name, push_refspec)
222→                            .map(|_| ())
223→                    })
224→                    .map_err(CoreError::Git)?;
225→            }
226→        }
227→
228→        Ok(())
229→    }
230→}
