  1→use std::collections::HashMap;
  2→use std::io::{Read, Write};
  3→use std::path::PathBuf;
  4→use std::sync::{Arc, Mutex};
  5→
  6→use chrono::{DateTime, Utc};
  7→use portable_pty::{native_pty_system, CommandBuilder, PtySize};
  8→
  9→use engram_core::model::FileChange;
 10→
 11→use crate::error::CaptureError;
 12→
 13→use super::detector::{detect_changes, snapshot_working_tree};
 14→
 15→/// Configuration for a PTY-wrapped agent session.
 16→#[derive(Debug, Clone)]
 17→pub struct PtyWrapperConfig {
 18→    pub command: String,
 19→    pub args: Vec<String>,
 20→    pub working_dir: PathBuf,
 21→    pub agent_name: Option<String>,
 22→}
 23→
 24→/// Result of a captured PTY session.
 25→#[derive(Debug, Clone)]
 26→pub struct CapturedSession {
 27→    pub raw_output: Vec<u8>,
 28→    pub start_time: DateTime<Utc>,
 29→    pub end_time: DateTime<Utc>,
 30→    pub exit_code: Option<u32>,
 31→    pub file_changes: Vec<FileChange>,
 32→    pub command: String,
 33→    pub args: Vec<String>,
 34→}
 35→
 36→/// A PTY session that captures agent output and detects file changes.
 37→pub struct PtySession {
 38→    config: PtyWrapperConfig,
 39→    file_snapshot_before: HashMap<PathBuf, Vec<u8>>,
 40→    start_time: DateTime<Utc>,
 41→}
 42→
 43→impl PtySession {
 44→    /// Start a new PTY session: snapshot the working tree.
 45→    pub fn start(config: PtyWrapperConfig) -> Result<Self, CaptureError> {
 46→        let snapshot = snapshot_working_tree(&config.working_dir)
 47→            .map_err(|e| CaptureError::Pty(format!("Failed to snapshot working tree: {e}")))?;
 48→
 49→        Ok(Self {
 50→            config,
 51→            file_snapshot_before: snapshot,
 52→            start_time: Utc::now(),
 53→        })
 54→    }
 55→
 56→    /// Run the session to completion. Spawns the command in a PTY,
 57→    /// passes stdin/stdout through, captures output.
 58→    pub fn run(self) -> Result<CapturedSession, CaptureError> {
 59→        let pty_system = native_pty_system();
 60→
 61→        // Get terminal size from current terminal, fall back to defaults
 62→        let (cols, rows) = terminal_size().unwrap_or((80, 24));
 63→
 64→        let pair = pty_system
 65→            .openpty(PtySize {
 66→                rows,
 67→                cols,
 68→                pixel_width: 0,
 69→                pixel_height: 0,
 70→            })
 71→            .map_err(|e| CaptureError::Pty(format!("Failed to open PTY: {e}")))?;
 72→
 73→        // Build the command
 74→        let mut cmd = CommandBuilder::new(&self.config.command);
 75→        cmd.args(&self.config.args);
 76→        cmd.cwd(&self.config.working_dir);
 77→
 78→        // Spawn the child process
 79→        let mut child = pair
 80→            .slave
 81→            .spawn_command(cmd)
 82→            .map_err(|e| CaptureError::Pty(format!("Failed to spawn command: {e}")))?;
 83→
 84→        // Drop the slave to avoid hanging
 85→        drop(pair.slave);
 86→
 87→        // Set up capture buffer
 88→        let capture_buffer = Arc::new(Mutex::new(Vec::new()));
 89→
 90→        // Get reader/writer from master
 91→        let mut reader = pair
 92→            .master
 93→            .try_clone_reader()
 94→            .map_err(|e| CaptureError::Pty(format!("Failed to clone PTY reader: {e}")))?;
 95→        let mut writer = pair
 96→            .master
 97→            .take_writer()
 98→            .map_err(|e| CaptureError::Pty(format!("Failed to take PTY writer: {e}")))?;
 99→
100→        // Reader thread: PTY output -> stdout + capture buffer
101→        let buf_clone = Arc::clone(&capture_buffer);
102→        let reader_handle = std::thread::spawn(move || {
103→            let mut buf = [0u8; 4096];
104→            loop {
105→                match reader.read(&mut buf) {
106→                    Ok(0) => break,
107→                    Ok(n) => {
108→                        // Pass through to stdout
109→                        let _ = std::io::stdout().write_all(&buf[..n]);
110→                        let _ = std::io::stdout().flush();
111→                        // Capture
112→                        if let Ok(mut capture) = buf_clone.lock() {
113→                            capture.extend_from_slice(&buf[..n]);
114→                        }
115→                    }
116→                    Err(_) => break,
117→                }
118→            }
119→        });
120→
121→        // Writer thread: stdin -> PTY
122→        let writer_handle = std::thread::spawn(move || {
123→            let mut buf = [0u8; 4096];
124→            loop {
125→                match std::io::stdin().read(&mut buf) {
126→                    Ok(0) => break,
127→                    Ok(n) => {
128→                        if writer.write_all(&buf[..n]).is_err() {
129→                            break;
130→                        }
131→                    }
132→                    Err(_) => break,
133→                }
134→            }
135→        });
136→
137→        // Wait for child to exit
138→        let status = child
139→            .wait()
140→            .map_err(|e| CaptureError::Pty(format!("Failed to wait for child: {e}")))?;
141→
142→        // Wait for reader to finish (writer may hang on stdin, so don't join it)
143→        let _ = reader_handle.join();
144→        drop(writer_handle); // Don't wait for stdin thread
145→
146→        let end_time = Utc::now();
147→        let exit_code = Some(status.exit_code());
148→
149→        // Detect file changes
150→        let snapshot_after = snapshot_working_tree(&self.config.working_dir)
151→            .map_err(|e| CaptureError::Pty(format!("Failed to snapshot working tree: {e}")))?;
152→        let file_changes = detect_changes(&self.file_snapshot_before, &snapshot_after);
153→
154→        // Collect captured output
155→        let raw_output = capture_buffer
156→            .lock()
157→            .map(|buf| buf.clone())
158→            .unwrap_or_default();
159→
160→        Ok(CapturedSession {
161→            raw_output,
162→            start_time: self.start_time,
163→            end_time,
164→            exit_code,
165→            file_changes,
166→            command: self.config.command,
167→            args: self.config.args,
168→        })
169→    }
170→}
171→
172→/// Try to get the current terminal size from environment variables.
173→fn terminal_size() -> Option<(u16, u16)> {
174→    // Try COLUMNS and LINES env vars (set by many terminals)
175→    let cols = std::env::var("COLUMNS")
176→        .ok()
177→        .and_then(|v| v.parse::<u16>().ok());
178→    let rows = std::env::var("LINES")
179→        .ok()
180→        .and_then(|v| v.parse::<u16>().ok());
181→
182→    match (cols, rows) {
183→        (Some(c), Some(r)) if c > 0 && r > 0 => Some((c, r)),
184→        _ => None,
185→    }
186→}
