  6→/// The ref prefix for all engram refs.
  7→pub const ENGRAM_REF_PREFIX: &str = "refs/engrams/";
  8→
  9→/// Build the full ref name for an engram: refs/engrams/<ab>/<full-id>
 10→pub fn engram_ref_name(id: &EngramId) -> String {
 11→    format!("refs/engrams/{}/{}", id.fanout_prefix(), id.as_str())
 12→}
 13→
 14→/// Create or update the ref for an engram.
 15→pub fn create_engram_ref(
 16→    repo: &Repository,
 17→    id: &EngramId,
 18→    commit_oid: Oid,
 19→) -> Result<(), CoreError> {
 20→    let ref_name = engram_ref_name(id);
 21→    repo.reference(&ref_name, commit_oid, true, "engram: create")?;
 22→    Ok(())
 23→}
 24→
 25→/// Delete the ref for an engram.
 26→pub fn delete_engram_ref(repo: &Repository, id: &EngramId) -> Result<(), CoreError> {
 27→    let ref_name = engram_ref_name(id);
 28→    let mut reference = repo.find_reference(&ref_name)?;
 29→    reference.delete()?;
 30→    Ok(())
 31→}
 32→
 33→/// List all engram ref names using glob. Returns (EngramId, commit Oid) pairs.
 34→pub fn list_engram_refs(repo: &Repository) -> Result<Vec<(EngramId, Oid)>, CoreError> {
 35→    let mut results = Vec::new();
 36→    let pattern = format!("{ENGRAM_REF_PREFIX}*/*");
 37→    let refs = repo.references_glob(&pattern)?;
 38→    for reference in refs {
 39→        let reference = reference?;
 40→        if let (Some(name), Some(oid)) = (reference.name(), reference.target()) {
 41→            // Extract the ID from refs/engrams/ab/full-id
 42→            if let Some(id_part) = name.strip_prefix(ENGRAM_REF_PREFIX) {
 43→                // id_part is "ab/full-id"
 44→                if let Some((_prefix, full_id)) = id_part.split_once('/') {
 45→                    results.push((EngramId(full_id.to_string()), oid));
 46→                }
 47→            }
 48→        }
 49→    }
 50→    Ok(results)
 51→}
 52→
 53→/// Resolve an engram ID (or prefix) to its full ID and commit Oid.
 54→pub fn resolve_engram_ref(
 55→    repo: &Repository,
 56→    id_or_prefix: &str,
 57→) -> Result<(EngramId, Oid), CoreError> {
 58→    // First try exact match
 59→    let exact_id = EngramId(id_or_prefix.to_string());
 60→    let ref_name = engram_ref_name(&exact_id);
 61→    if let Ok(reference) = repo.find_reference(&ref_name) {
 62→        if let Some(oid) = reference.target() {
 63→            return Ok((exact_id, oid));
 64→        }
 65→    }
 66→
 67→    // Try prefix match
 68→    let all_refs = list_engram_refs(repo)?;
 69→    let matches: Vec<_> = all_refs
 70→        .iter()
 71→        .filter(|(id, _)| id.as_str().starts_with(id_or_prefix))
 72→        .collect();
 73→
 74→    match matches.len() {
 75→        0 => Err(CoreError::NotFound {
 76→            id: id_or_prefix.to_string(),
 77→        }),
 78→        1 => Ok(matches[0].clone()),
 79→        _ => Err(CoreError::Parse(format!(
 80→            "Ambiguous engram ID prefix '{}': {} matches",
 81→            id_or_prefix,
 82→            matches.len()
 83→        ))),
 84→    }
 85→}
