 10→/// Import a Claude Code session from a JSONL file.
 11→pub struct ClaudeCodeImporter;
 12→
 13→impl ClaudeCodeImporter {
 14→    /// Discover the Claude Code projects directory.
 15→    pub fn projects_dir() -> Option<PathBuf> {
 16→        dirs_for_claude_projects()
 17→    }
 18→
 19→    /// Discover all session files for a project.
 20→    pub fn discover_sessions(project_path: &Path) -> Result<Vec<PathBuf>, CaptureError> {
 21→        let project_key = path_to_claude_key(project_path);
 22→        let projects_dir = Self::projects_dir()
 23→            .ok_or_else(|| CaptureError::Import("Cannot find ~/.claude/projects".into()))?;
 24→        let project_dir = projects_dir.join(&project_key);
 25→
 26→        if !project_dir.exists() {
 27→            return Ok(Vec::new());
 28→        }
 29→
 30→        let mut sessions = Vec::new();
 31→        for entry in std::fs::read_dir(&project_dir).map_err(CaptureError::Io)? {
 32→            let entry = entry.map_err(CaptureError::Io)?;
 33→            let path = entry.path();
 34→            if path.extension().is_some_and(|e| e == "jsonl") && path.is_file() {
 35→                sessions.push(path);
 36→            }
 37→        }
 38→        sessions.sort();
 39→        Ok(sessions)
 40→    }
 41→
 42→    /// Import a single session JSONL file into an EngramData.
 43→    pub fn import_session(path: &Path) -> Result<EngramData, CaptureError> {
 44→        let content = std::fs::read_to_string(path).map_err(CaptureError::Io)?;
 45→        parse_claude_code_session(&content)
 46→    }
 47→}
 48→
 49→/// Internal Claude Code JSONL entry.
 50→#[derive(Debug, Deserialize)]
 51→struct ClaudeEntry {
 52→    #[serde(rename = "type")]
 53→    entry_type: String,
 54→    #[serde(default)]
 55→    _uuid: Option<String>,
 56→    #[serde(default, rename = "parentUuid")]
 57→    _parent_uuid: Option<String>,
 58→    #[serde(default)]
 59→    timestamp: Option<String>,
 60→    #[serde(default)]
 61→    message: Option<ClaudeMessage>,
 62→    #[serde(default, rename = "isSidechain")]
 63→    is_sidechain: Option<bool>,
 64→}
 65→
 66→#[derive(Debug, Deserialize)]
 67→struct ClaudeMessage {
 68→    role: String,
 69→    #[serde(default)]
 70→    content: serde_json::Value,
 71→    #[serde(default)]
 72→    model: Option<String>,
 73→    #[serde(default)]
 74→    usage: Option<ClaudeUsage>,
 75→}
 76→
 77→#[derive(Debug, Deserialize)]
 78→struct ClaudeUsage {
 79→    #[serde(default)]
 80→    input_tokens: Option<u64>,
 81→    #[serde(default)]
 82→    output_tokens: Option<u64>,
 83→    #[serde(default)]
 84→    cache_creation_input_tokens: Option<u64>,
 85→    #[serde(default)]
 86→    cache_read_input_tokens: Option<u64>,
 87→}
 88→
 89→fn parse_claude_code_session(content: &str) -> Result<EngramData, CaptureError> {
 90→    let mut entries = Vec::new();
 91→    let mut first_timestamp: Option<DateTime<Utc>> = None;
 92→    let mut last_timestamp: Option<DateTime<Utc>> = None;
 93→    let mut model_name: Option<String> = None;
 94→    let mut agent_version: Option<String> = None;
 95→    let mut token_usage = TokenUsage::default();
 96→    let mut transcript_entries = Vec::new();
 97→    let mut tool_calls = Vec::new();
 98→    let mut file_changes = Vec::new();
 99→    let mut original_request = String::new();
100→
101→    // Parse all lines
102→    for line in content.lines() {
103→        if line.trim().is_empty() {
104→            continue;
105→        }
106→        match serde_json::from_str::<ClaudeEntry>(line) {
107→            Ok(entry) => entries.push(entry),
108→            Err(e) => {
109→                tracing::debug!("Skipping unparseable JSONL line: {e}");
110→            }
111→        }
112→    }
113→
114→    for entry in &entries {
115→        // Skip non-message entries
116→        if !matches!(entry.entry_type.as_str(), "user" | "assistant") {
117→            continue;
118→        }
119→
120→        // Skip sidechain messages
121→        if entry.is_sidechain == Some(true) {
122→            continue;
123→        }
124→
125→        // Parse timestamp
126→        let ts = entry
127→            .timestamp
128→            .as_deref()
129→            .and_then(|t| t.parse::<DateTime<Utc>>().ok());
130→
131→        if let Some(ts) = ts {
132→            if first_timestamp.is_none() {
133→                first_timestamp = Some(ts);
134→            }
135→            last_timestamp = Some(ts);
136→        }
137→
138→        let Some(msg) = &entry.message else {
139→            continue;
140→        };
141→
142→        // Extract model and version from first assistant message
143→        if msg.role == "assistant" && model_name.is_none() {
144→            model_name = msg.model.clone();
145→        }
146→
147→        // Accumulate token usage
148→        if let Some(usage) = &msg.usage {
149→            token_usage.input_tokens += usage.input_tokens.unwrap_or(0);
150→            token_usage.output_tokens += usage.output_tokens.unwrap_or(0);
151→            token_usage.cache_read_tokens += usage.cache_read_input_tokens.unwrap_or(0);
152→            token_usage.cache_write_tokens += usage.cache_creation_input_tokens.unwrap_or(0);
153→        }
154→
155→        // Process message content
156→        let role = match msg.role.as_str() {
157→            "user" => Role::User,
158→            "assistant" => Role::Assistant,
159→            _ => continue,
160→        };
161→
162→        // Content can be a string or array of content blocks
163→        match &msg.content {
164→            serde_json::Value::String(text) => {
165→                if role == Role::User && original_request.is_empty() {
166→                    original_request = text.clone();
167→                }
168→                transcript_entries.push(TranscriptEntry {
169→                    timestamp: ts.unwrap_or_else(Utc::now),
170→                    role,
171→                    content: TranscriptContent::Text { text: text.clone() },
172→                    token_count: None,
173→                });
174→            }
175→            serde_json::Value::Array(blocks) => {
176→                for block in blocks {
177→                    let block_type = block.get("type").and_then(|t| t.as_str()).unwrap_or("");
178→
179→                    match block_type {
180→                        "text" => {
181→                            let text = block
182→                                .get("text")
183→                                .and_then(|t| t.as_str())
184→                                .unwrap_or("")
185→                                .to_string();
186→
187→                            if role == Role::User && original_request.is_empty() {
188→                                original_request = text.clone();
189→                            }
190→
191→                            transcript_entries.push(TranscriptEntry {
192→                                timestamp: ts.unwrap_or_else(Utc::now),
193→                                role: role.clone(),
194→                                content: TranscriptContent::Text { text },
195→                                token_count: None,
196→                            });
197→                        }
198→                        "tool_use" => {
199→                            let tool_name = block
200→                                .get("name")
201→                                .and_then(|n| n.as_str())
202→                                .unwrap_or("unknown")
203→                                .to_string();
204→                            let tool_id = block
205→                                .get("id")
206→                                .and_then(|n| n.as_str())
207→                                .unwrap_or("")
208→                                .to_string();
209→                            let input = block
210→                                .get("input")
211→                                .cloned()
212→                                .unwrap_or(serde_json::Value::Null);
213→
214→                            // Track file operations
215→                            if matches!(tool_name.as_str(), "Write" | "Edit" | "NotebookEdit") {
216→                                if let Some(path) = input.get("file_path").and_then(|p| p.as_str())
217→                                {
218→                                    let change_type = if tool_name == "Write" {
219→                                        FileChangeType::Created
220→                                    } else {
221→                                        FileChangeType::Modified
222→                                    };
223→                                    if !file_changes.iter().any(|fc: &FileChange| fc.path == path) {
224→                                        file_changes.push(FileChange {
225→                                            path: path.to_string(),
226→                                            change_type,
227→                                            lines_added: None,
228→                                            lines_removed: None,
229→                                        });
230→                                    }
231→                                }
232→                            }
233→
234→                            tool_calls.push(ToolCall {
235→                                timestamp: ts.unwrap_or_else(Utc::now),
236→                                tool_name: tool_name.clone(),
237→                                input: input.clone(),
238→                                output_summary: None,
239→                                duration_ms: None,
240→                                is_error: false,
241→                            });
242→
243→                            transcript_entries.push(TranscriptEntry {
244→                                timestamp: ts.unwrap_or_else(Utc::now),
245→                                role: role.clone(),
246→                                content: TranscriptContent::ToolUse {
247→                                    tool_name,
248→                                    tool_id,
249→                                    input,
250→                                },
251→                                token_count: None,
252→                            });
253→                        }
254→                        "tool_result" => {
255→                            let tool_id = block
256→                                .get("tool_use_id")
257→                                .and_then(|n| n.as_str())
258→                                .unwrap_or("")
259→                                .to_string();
260→                            let output = block
261→                                .get("content")
262→                                .and_then(|c| c.as_str())
263→                                .unwrap_or("")
264→                                .to_string();
265→                            let is_error = block
266→                                .get("is_error")
267→                                .and_then(|e| e.as_bool())
268→                                .unwrap_or(false);
269→
270→                            transcript_entries.push(TranscriptEntry {
271→                                timestamp: ts.unwrap_or_else(Utc::now),
272→                                role: Role::Tool,
273→                                content: TranscriptContent::ToolResult {
274→                                    tool_id,
275→                                    output,
276→                                    is_error,
277→                                },
278→                                token_count: None,
279→                            });
280→                        }
281→                        "thinking" => {
282→                            let text = block
283→                                .get("thinking")
284→                                .and_then(|t| t.as_str())
285→                                .unwrap_or("")
286→                                .to_string();
287→                            if !text.is_empty() {
288→                                transcript_entries.push(TranscriptEntry {
289→                                    timestamp: ts.unwrap_or_else(Utc::now),
290→                                    role: role.clone(),
291→                                    content: TranscriptContent::Thinking { text },
292→                                    token_count: None,
293→                                });
294→                            }
295→                        }
296→                        _ => {}
297→                    }
298→                }
299→            }
300→            _ => {}
301→        }
302→    }
303→
304→    // Try to get version from the first JSON line
305→    if let Some(v) = content
306→        .lines()
307→        .next()
308→        .and_then(|line| serde_json::from_str::<serde_json::Value>(line).ok())
309→        .and_then(|v| v.get("version").and_then(|v| v.as_str()).map(String::from))
310→    {
311→        agent_version = Some(v);
312→    }
313→
314→    token_usage.total_tokens = token_usage.input_tokens
315→        + token_usage.output_tokens
316→        + token_usage.cache_read_tokens
317→        + token_usage.cache_write_tokens;
318→
319→    let now = Utc::now();
320→    let created_at = first_timestamp.unwrap_or(now);
321→    let finished_at = last_timestamp.unwrap_or(now);
322→
323→    let id = EngramId::new();
324→
325→    let manifest = Manifest {
326→        id,
327→        version: 1,
328→        created_at,
329→        finished_at: Some(finished_at),
330→        agent: AgentInfo {
331→            name: "claude-code".into(),
332→            model: model_name,
333→            version: agent_version,
334→        },
335→        git_commits: Vec::new(),
336→        token_usage,
337→        summary: if original_request.len() > 100 {
338→            Some(format!("{}...", &original_request[..100]))
339→        } else if original_request.is_empty() {
340→            Some("Imported Claude Code session".into())
341→        } else {
342→            Some(original_request.clone())
343→        },
344→        tags: Vec::new(),
345→        capture_mode: CaptureMode::Import,
346→    };
347→
348→    let intent = Intent {
349→        original_request: if original_request.is_empty() {
350→            "Imported Claude Code session".into()
351→        } else {
352→            original_request
353→        },
354→        interpreted_goal: None,
355→        summary: manifest.summary.clone(),
356→        dead_ends: Vec::new(),
357→        decisions: Vec::new(),
358→    };
359→
360→    let operations = Operations {
361→        tool_calls,
362→        file_changes,
363→        shell_commands: Vec::new(),
364→    };
365→
366→    Ok(EngramData {
367→        manifest,
368→        intent,
369→        transcript: Transcript {
370→            entries: transcript_entries,
371→        },
372→        operations,
373→        lineage: Lineage::default(),
374→    })
375→}
