377→/// Convert a filesystem path to Claude Code's project key format.
378→/// /Users/sjonas/myproject -> -Users-sjonas-myproject
379→fn path_to_claude_key(path: &Path) -> String {
380→    path.to_string_lossy().replace('/', "-")
381→}
