383→fn dirs_for_claude_projects() -> Option<PathBuf> {
384→    // ~/.claude/projects/
385→    home_dir().map(|h| h.join(".claude").join("projects"))
386→}
387→
388→fn home_dir() -> Option<PathBuf> {
389→    std::env::var_os("HOME").map(PathBuf::from)
390→}
