 31→fn parse_aider_history(content: &str) -> Result<Vec<EngramData>, CaptureError> {
 32→    let mut engrams = Vec::new();
 33→
 34→    // Split by session headers
 35→    let sessions: Vec<&str> = content.split("# aider chat started at").collect();
 36→
 37→    for session_text in sessions.iter().skip(1) {
 38→        // Skip the first empty split
 39→        if let Some(engram) = parse_aider_session(session_text)? {
 40→            engrams.push(engram);
 41→        }
 42→    }
 43→
 44→    // If no session headers found, treat the whole file as one session
 45→    if engrams.is_empty() && !content.trim().is_empty() {
 46→        if let Some(engram) = parse_aider_session(content)? {
 47→            engrams.push(engram);
 48→        }
 49→    }
 50→
 51→    Ok(engrams)
 52→}
 53→
 54→fn parse_aider_session(session_text: &str) -> Result<Option<EngramData>, CaptureError> {
 55→    let mut transcript_entries = Vec::new();
 56→    let mut original_request = String::new();
 57→    let mut total_tokens_sent: u64 = 0;
 58→    let mut total_tokens_received: u64 = 0;
 59→    let mut total_cost: f64 = 0.0;
 60→
 61→    let mut current_role: Option<Role> = None;
 62→    let mut current_text = String::new();
 63→    let now = Utc::now();
 64→
 65→    for line in session_text.lines() {
 66→        // User message starts with ####
 67→        if let Some(user_msg) = line.strip_prefix("#### ") {
 68→            // Save any previous accumulated text
 69→            flush_entry(&mut transcript_entries, &current_role, &current_text, now);
 70→
 71→            let msg = user_msg.trim().to_string();
 72→            if original_request.is_empty() && !msg.is_empty() {
 73→                original_request = msg.clone();
 74→            }
 75→
 76→            if !msg.is_empty() {
 77→                transcript_entries.push(TranscriptEntry {
 78→                    timestamp: now,
 79→                    role: Role::User,
 80→                    content: TranscriptContent::Text { text: msg },
 81→                    token_count: None,
 82→                });
 83→            }
 84→            current_role = None;
 85→            current_text.clear();
 86→            continue;
 87→        }
 88→
 89→        // Tool output / system messages start with >
 90→        if line.starts_with("> ") {
 91→            let tool_text = line.strip_prefix("> ").unwrap_or(line);
 92→
 93→            // Parse token/cost lines: "Tokens: 3.2k sent, 245 received. Cost: $0.01"
 94→            if tool_text.starts_with("Tokens:") {
 95→                parse_token_line(
 96→                    tool_text,
 97→                    &mut total_tokens_sent,
 98→                    &mut total_tokens_received,
 99→                    &mut total_cost,
100→                );
101→            }
102→            continue;
103→        }
104→
105→        // Unprefixed text = assistant response
106→        if !line.is_empty() {
107→            if current_role.is_none() {
108→                current_role = Some(Role::Assistant);
109→            }
110→            if !current_text.is_empty() {
111→                current_text.push('\n');
112→            }
113→            current_text.push_str(line);
114→        }
115→    }
116→
117→    // Flush last entry
118→    flush_entry(&mut transcript_entries, &current_role, &current_text, now);
119→
120→    if transcript_entries.is_empty() {
121→        return Ok(None);
122→    }
123→
124→    let id = EngramId::new();
125→    let token_usage = TokenUsage {
126→        input_tokens: total_tokens_sent,
127→        output_tokens: total_tokens_received,
128→        total_tokens: total_tokens_sent + total_tokens_received,
129→        cost_usd: if total_cost > 0.0 {
130→            Some(total_cost)
131→        } else {
132→            None
133→        },
134→        ..Default::default()
135→    };
136→
137→    let manifest = Manifest {
138→        id,
139→        version: 1,
140→        created_at: now,
141→        finished_at: Some(now),
142→        agent: AgentInfo {
143→            name: "aider".into(),
144→            model: None,
145→            version: None,
146→        },
147→        git_commits: Vec::new(),
148→        token_usage,
149→        summary: if original_request.len() > 100 {
150→            Some(format!("{}...", &original_request[..100]))
151→        } else if original_request.is_empty() {
152→            Some("Imported Aider session".into())
153→        } else {
154→            Some(original_request.clone())
155→        },
156→        tags: Vec::new(),
157→        capture_mode: CaptureMode::Import,
158→    };
159→
160→    let intent = Intent {
161→        original_request: if original_request.is_empty() {
162→            "Imported Aider session".into()
163→        } else {
164→            original_request
165→        },
166→        interpreted_goal: None,
167→        summary: manifest.summary.clone(),
168→        dead_ends: Vec::new(),
169→        decisions: Vec::new(),
170→    };
171→
172→    Ok(Some(EngramData {
173→        manifest,
174→        intent,
175→        transcript: Transcript {
176→            entries: transcript_entries,
177→        },
178→        operations: Operations::default(),
179→        lineage: Lineage::default(),
180→    }))
181→}
182→
183→fn flush_entry(
184→    entries: &mut Vec<TranscriptEntry>,
185→    role: &Option<Role>,
186→    text: &str,
187→    ts: chrono::DateTime<Utc>,
188→) {
189→    if let Some(role) = role {
190→        let trimmed = text.trim();
191→        if !trimmed.is_empty() {
192→            entries.push(TranscriptEntry {
193→                timestamp: ts,
194→                role: role.clone(),
195→                content: TranscriptContent::Text {
196→                    text: trimmed.to_string(),
197→                },
198→                token_count: None,
199→            });
200→        }
201→    }
202→}
203→
204→fn parse_token_line(line: &str, sent: &mut u64, received: &mut u64, cost: &mut f64) {
205→    // Format: "Tokens: 3.2k sent, 245 received. Cost: $0.01"
206→    // or: "Tokens: 3200 sent, 245 received."
207→    // Split on ',' only (not '.') to preserve decimal numbers like 3.2k and $0.01
208→    for part in line.split(',') {
209→        let part = part.trim();
210→        if part.contains("sent") {
211→            if let Some(num) = extract_token_count(part) {
212→                *sent += num;
213→            }
214→        }
215→        if part.contains("received") {
216→            if let Some(num) = extract_token_count(part) {
217→                *received += num;
218→            }
219→        }
220→        if part.contains('$') {
221→            if let Some(c) = extract_cost(part) {
222→                *cost += c;
223→            }
224→        }
225→    }
226→}
227→
228→fn extract_token_count(s: &str) -> Option<u64> {
229→    // Find a number (possibly with k/m suffix)
230→    for word in s.split_whitespace() {
231→        let word = word.trim_matches(|c: char| {
232→            !c.is_ascii_digit() && c != '.' && c != 'k' && c != 'K' && c != 'm' && c != 'M'
233→        });
234→        if word.is_empty() {
235→            continue;
236→        }
237→        if let Some(num_str) = word.strip_suffix('k').or_else(|| word.strip_suffix('K')) {
238→            if let Ok(n) = num_str.parse::<f64>() {
239→                return Some((n * 1000.0) as u64);
240→            }
241→        } else if let Some(num_str) = word.strip_suffix('m').or_else(|| word.strip_suffix('M')) {
242→            if let Ok(n) = num_str.parse::<f64>() {
243→                return Some((n * 1_000_000.0) as u64);
244→            }
245→        } else if let Ok(n) = word.parse::<u64>() {
246→            return Some(n);
247→        }
248→    }
249→    None
250→}
251→
252→fn extract_cost(s: &str) -> Option<f64> {
253→    for word in s.split_whitespace() {
254→        if let Some(num_str) = word.strip_prefix('$') {
255→            if let Ok(c) = num_str.parse::<f64>() {
256→                return Some(c);
257→            }
258→        }
259→    }
260→    None
261→}
