49→        self.ensure_index(storage)?;
50→        let searcher = EngramSearcher::open(&self.index_path)?;
51→        searcher.search_by_file(file_path, limit)
52→    }
53→
54→    /// Index a single new engram (incremental update).
55→    pub fn index_engram(&self, data: &EngramData) -> Result<(), QueryError> {
56→        if !self.index_path.exists() {
57→            return Ok(()); // Index doesn't exist yet, skip
58→        }
59→        let mut writer = EngramIndexWriter::open(&self.index_path)?;
60→        writer.index_engram(data)?;
61→        writer.commit()?;
62→        Ok(())
63→    }
64→
65→    /// Rebuild the index from scratch.
66→    pub fn rebuild(&self, storage: &GitStorage) -> Result<usize, QueryError> {
67→        rebuild_index(storage, &self.index_path)
68→    }
69→
70→    /// Return the index path.
71→    pub fn index_path(&self) -> &PathBuf {
72→        &self.index_path
73→    }
74→}
