 11→
 12→fn format_manifest_list_text(manifests: &[Manifest], show_cost: bool) -> String {
 13→    if manifests.is_empty() {
 14→        return "No engrams found.".to_string();
 15→    }
 16→
 17→    let mut out = String::new();
 18→    for m in manifests {
 19→        let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
 20→        let summary = m.summary.as_deref().unwrap_or("(no summary)");
 21→        let agent = &m.agent.name;
 22→        let model = m.agent.model.as_deref().unwrap_or("");
 23→        let time = m.created_at.format("%Y-%m-%d %H:%M");
 24→
 25→        if show_cost {
 26→            let tokens = m.token_usage.total_tokens;
 27→            let cost = m
 28→                .token_usage
 29→                .cost_usd
 30→                .map(|c| format!("${c:.2}"))
 31→                .unwrap_or_else(|| "-".to_string());
 32→            out.push_str(&format!(
 33→                "\u{25c6} {short_id} {summary} [{agent}/{model}] {cost} {tokens}tok  {time}\n"
 34→            ));
 35→        } else {
 36→            out.push_str(&format!(
 37→                "\u{25c6} {short_id} {summary} [{agent}/{model}]  {time}\n"
 38→            ));
 39→        }
 40→    }
 41→    out
 42→}
