 44→pub fn format_engram_full(data: &EngramData, fmt: OutputFormat) -> String {
 45→    match fmt {
 46→        OutputFormat::Json => serde_json::to_string_pretty(&data.manifest).unwrap_or_default(),
 47→        OutputFormat::Text => format_engram_full_text(data),
 48→    }
 49→}
 50→
 51→fn format_engram_full_text(data: &EngramData) -> String {
 52→    let m = &data.manifest;
 53→    let mut out = String::new();
 54→
 55→    out.push_str(&format!("Engram: {}\n", m.id));
 56→    out.push_str(&format!(
 57→        "Agent:  {}{}\n",
 58→        m.agent.name,
 59→        m.agent
 60→            .model
 61→            .as_ref()
 62→            .map(|m| format!(" ({m})"))
 63→            .unwrap_or_default()
 64→    ));
 65→    out.push_str(&format!(
 66→        "Date:   {}\n",
 67→        m.created_at.format("%Y-%m-%d %H:%M:%S UTC")
 68→    ));
 69→    if let Some(summary) = &m.summary {
 70→        out.push_str(&format!("Summary: {summary}\n"));
 71→    }
 72→
 73→    // Token usage
 74→    let tu = &m.token_usage;
 75→    if tu.total_tokens > 0 {
 76→        out.push_str(&format!(
 77→            "Tokens: {} total ({} in, {} out)",
 78→            tu.total_tokens, tu.input_tokens, tu.output_tokens
 79→        ));
 80→        if let Some(cost) = tu.cost_usd {
 81→            out.push_str(&format!("  Cost: ${cost:.4}"));
 82→        }
 83→        out.push('\n');
 84→    }
 85→
 86→    if !m.git_commits.is_empty() {
 87→        out.push_str(&format!("Commits: {}\n", m.git_commits.join(", ")));
 88→    }
 89→
 90→    if !m.tags.is_empty() {
 91→        out.push_str(&format!("Tags: {}\n", m.tags.join(", ")));
 92→    }
 93→
 94→    // Intent
 95→    out.push_str("\n--- Intent ---\n");
 96→    out.push_str(&data.intent.to_markdown());
 97→
 98→    // Operations summary
 99→    if !data.operations.file_changes.is_empty() {
100→        out.push_str("\n--- File Changes ---\n");
101→        for fc in &data.operations.file_changes {
102→            let symbol = match &fc.change_type {
103→                engram_core::model::FileChangeType::Created => "+",
104→                engram_core::model::FileChangeType::Modified => "~",
105→                engram_core::model::FileChangeType::Deleted => "-",
106→                engram_core::model::FileChangeType::Renamed { from } => {
107→                    out.push_str(&format!("  {from} -> {}\n", fc.path));
108→                    continue;
109→                }
110→            };
111→            out.push_str(&format!("  {symbol} {}\n", fc.path));
112→        }
113→    }
114→
115→    if !data.operations.tool_calls.is_empty() {
116→        out.push_str(&format!(
117→            "\n--- Tool Calls ({}) ---\n",
118→            data.operations.tool_calls.len()
119→        ));
120→        for tc in &data.operations.tool_calls {
121→            let err_marker = if tc.is_error { " [ERROR]" } else { "" };
122→            out.push_str(&format!("  {}{err_marker}\n", tc.tool_name));
123→        }
124→    }
125→
126→    // Transcript summary
127→    out.push_str(&format!(
128→        "\n--- Transcript ({} entries) ---\n",
129→        data.transcript.entries.len()
130→    ));
131→
132→    out
133→}
