  1→use serde::{Deserialize, Serialize};
  2→
  3→use crate::error::CoreError;
  4→
  5→/// Structured intent data, stored as intent.md (Markdown) in the engram tree.
  6→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
  7→pub struct Intent {
  8→    pub original_request: String,
  9→    #[serde(default, skip_serializing_if = "Option::is_none")]
 10→    pub interpreted_goal: Option<String>,
 11→    #[serde(default, skip_serializing_if = "Option::is_none")]
 12→    pub summary: Option<String>,
 13→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 14→    pub dead_ends: Vec<DeadEnd>,
 15→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 16→    pub decisions: Vec<Decision>,
 17→}
 18→
 19→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
 20→pub struct DeadEnd {
 21→    pub approach: String,
 22→    pub reason: String,
 23→}
 24→
 25→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
 26→pub struct Decision {
 27→    pub description: String,
 28→    pub rationale: String,
 29→}
 30→
 31→impl Intent {
 32→    /// Render as Markdown for storage as intent.md
 33→    pub fn to_markdown(&self) -> String {
 34→        let mut md = String::new();
 35→
 36→        md.push_str("# Intent\n\n");
 37→        md.push_str(&self.original_request);
 38→        md.push('\n');
 39→
 40→        if let Some(goal) = &self.interpreted_goal {
 41→            md.push_str("\n## Interpreted Goal\n\n");
 42→            md.push_str(goal);
 43→            md.push('\n');
 44→        }
 45→
 46→        if let Some(summary) = &self.summary {
 47→            md.push_str("\n## Summary\n\n");
 48→            md.push_str(summary);
 49→            md.push('\n');
 50→        }
 51→
 52→        if !self.dead_ends.is_empty() {
 53→            md.push_str("\n## Dead Ends\n\n");
 54→            for de in &self.dead_ends {
 55→                md.push_str(&format!("- **{}**: {}\n", de.approach, de.reason));
 56→            }
 57→        }
 58→
 59→        if !self.decisions.is_empty() {
 60→            md.push_str("\n## Decisions\n\n");
 61→            for d in &self.decisions {
 62→                md.push_str(&format!("- **{}**: {}\n", d.description, d.rationale));
 63→            }
 64→        }
 65→
 66→        md
 67→    }
 68→
 69→    /// Parse from Markdown
 70→    pub fn from_markdown(md: &str) -> Result<Self, CoreError> {
 71→        let mut original_request = String::new();
 72→        let mut interpreted_goal = None;
 73→        let mut summary = None;
 74→        let mut dead_ends = Vec::new();
 75→        let mut decisions = Vec::new();
 76→
 77→        let mut current_section = "intent";
 78→        let mut current_content = String::new();
 79→
 80→        for line in md.lines() {
 81→            if line.starts_with("# Intent") {
 82→                current_section = "intent";
 83→                current_content.clear();
 84→                continue;
 85→            } else if line.starts_with("## Original Request") {
 86→                // Backward compat: treat as intent section (some SDKs used this heading)
 87→                Self::save_section(
 88→                    current_section,
 89→                    &current_content,
 90→                    &mut original_request,
 91→                    &mut interpreted_goal,
 92→                    &mut summary,
 93→                );
 94→                current_section = "intent";
 95→                current_content.clear();
 96→                continue;
 97→            } else if line.starts_with("## Interpreted Goal") {
 98→                // Save previous section
 99→                Self::save_section(
100→                    current_section,
101→                    &current_content,
102→                    &mut original_request,
103→                    &mut interpreted_goal,
104→                    &mut summary,
105→                );
106→                current_section = "goal";
107→                current_content.clear();
108→                continue;
109→            } else if line.starts_with("## Summary") {
110→                Self::save_section(
111→                    current_section,
112→                    &current_content,
113→                    &mut original_request,
114→                    &mut interpreted_goal,
115→                    &mut summary,
116→                );
117→                current_section = "summary";
118→                current_content.clear();
119→                continue;
120→            } else if line.starts_with("## Dead Ends") {
121→                Self::save_section(
122→                    current_section,
123→                    &current_content,
124→                    &mut original_request,
125→                    &mut interpreted_goal,
126→                    &mut summary,
127→                );
128→                current_section = "dead_ends";
129→                current_content.clear();
130→                continue;
131→            } else if line.starts_with("## Decisions") {
132→                Self::save_section(
133→                    current_section,
134→                    &current_content,
135→                    &mut original_request,
136→                    &mut interpreted_goal,
137→                    &mut summary,
138→                );
139→                current_section = "decisions";
140→                current_content.clear();
141→                continue;
142→            }
143→
144→            match current_section {
145→                "dead_ends" => {
146→                    if let Some(entry) = line.strip_prefix("- **") {
147→                        if let Some((approach, reason)) = entry.split_once("**: ") {
148→                            dead_ends.push(DeadEnd {
149→                                approach: approach.to_string(),
150→                                reason: reason.to_string(),
151→                            });
152→                        }
153→                    }
154→                }
155→                "decisions" => {
156→                    if let Some(entry) = line.strip_prefix("- **") {
157→                        if let Some((desc, rationale)) = entry.split_once("**: ") {
158→                            decisions.push(Decision {
159→                                description: desc.to_string(),
160→                                rationale: rationale.to_string(),
161→                            });
162→                        }
163→                    }
164→                }
165→                _ => {
166→                    if !current_content.is_empty() || !line.is_empty() {
167→                        if !current_content.is_empty() {
168→                            current_content.push('\n');
169→                        }
170→                        current_content.push_str(line);
171→                    }
172→                }
173→            }
174→        }
175→
176→        // Save last section
177→        Self::save_section(
178→            current_section,
179→            &current_content,
180→            &mut original_request,
181→            &mut interpreted_goal,
182→            &mut summary,
183→        );
184→
185→        Ok(Intent {
186→            original_request,
187→            interpreted_goal,
188→            summary,
189→            dead_ends,
190→            decisions,
191→        })
192→    }
193→
194→    fn save_section(
195→        section: &str,
196→        content: &str,
197→        original_request: &mut String,
198→        interpreted_goal: &mut Option<String>,
199→        summary: &mut Option<String>,
200→    ) {
201→        let trimmed = content.trim().to_string();
202→        if trimmed.is_empty() {
203→            return;
204→        }
205→        match section {
206→            "intent" => *original_request = trimmed,
207→            "goal" => *interpreted_goal = Some(trimmed),
208→            "summary" => *summary = Some(trimmed),
209→            _ => {}
210→        }
211→    }
212→}
213→
214→#[cfg(test)]
215→mod tests {
216→    use super::*;
217→
218→    #[test]
219→    fn test_markdown_roundtrip() {
220→        let intent = Intent {
221→            original_request: "Add OAuth2 authentication".into(),
222→            interpreted_goal: Some("Implement OAuth2 with PKCE for the SPA".into()),
223→            summary: Some("Implemented OAuth2 with custom middleware".into()),
224→            dead_ends: vec![
225→                DeadEnd {
226→                    approach: "passport.js".into(),
227→                    reason: "Middleware conflict with existing stack".into(),
228→                },
229→                DeadEnd {
230→                    approach: "Auth0 SDK".into(),
231→                    reason: "Added 2MB to bundle".into(),
232→                },
233→            ],
234→            decisions: vec![Decision {
235→                description: "Custom middleware".into(),
236→                rationale: "Full control over auth flow".into(),
237→            }],
238→        };
239→
240→        let md = intent.to_markdown();
241→        let parsed = Intent::from_markdown(&md).unwrap();
242→
243→        assert_eq!(intent.original_request, parsed.original_request);
244→        assert_eq!(intent.interpreted_goal, parsed.interpreted_goal);
245→        assert_eq!(intent.summary, parsed.summary);
246→        assert_eq!(intent.dead_ends.len(), parsed.dead_ends.len());
247→        assert_eq!(intent.dead_ends[0].approach, parsed.dead_ends[0].approach);
248→        assert_eq!(intent.decisions.len(), parsed.decisions.len());
249→    }
250→
251→    #[test]
252→    fn test_minimal_intent() {
253→        let intent = Intent {
254→            original_request: "Fix the bug".into(),
255→            interpreted_goal: None,
256→            summary: None,
257→            dead_ends: vec![],
258→            decisions: vec![],
259→        };
260→        let md = intent.to_markdown();
